const icon = (name, cls = '') => `<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${iconPaths[name] || iconPaths.grid}</svg>`;
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = n => Number(n).toLocaleString('ru-RU');
const salary = (a, b) => Number.isFinite(a)&&Number.isFinite(b)?`${money(a)}–${money(b)} ₽`:Number.isFinite(a)?`от ${money(a)} ₽`:Number.isFinite(b)?`до ${money(b)} ₽`:'Зарплата не указана';
const initials = name => name.split(' ').slice(0,2).map(x => x[0] || '').join('');

