const status=s=>badge(statusLabel[s]||s,['accepted','shortlisted','reviewed'].includes(s)?'green':'');
const formatMoneyInput=value=>String(value??'').replace(/[^0-9]/g,'').replace(/^0+(?=\d)/,'').replace(/\B(?=(\d{3})+(?!\d))/g,'.');
const field=(label,name,value='',type='text',attrs='')=>{const amount=type==='number'&&['min','max'].includes(name);return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" value="${esc(amount?formatMoneyInput(value):value)}" type="${amount?'text':type}" ${amount?'data-money inputmode="numeric" autocomplete="off" maxlength="14"':''} ${amount?attrs.replace(/(?:min|max)="[^"]*"/g,''):attrs}></div>`;};
const textarea=(label,name,value='',attrs='')=>`<div class="field"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}" ${attrs}>${esc(value)}</textarea></div>`;
