const choiceGrid=(name,values,current=[])=>`<div class="choice-grid">${values.map(value=>`<label><input type="checkbox" name="${name}" value="${esc(value)}" ${current.includes(value)?'checked':''}><span>${esc(value)}</span></label>`).join('')}</div>`;
const radioGrid=(name,values,current)=>`<div class="choice-grid radio-grid">${values.map(value=>`<label><input type="radio" name="${name}" value="${esc(value)}" ${current===value?'checked':''} required><span>${esc(value)}</span></label>`).join('')}</div>`;

















function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4500);}
// Team context travels with the need text, so every refresh keeps the same ranking.
let needContext={team:'',format:'',city:'',budgetMin:'',budgetMax:''},contextDraft=null,contextOpen=null,activeNeed=null;
async function requestData(url,options={},read='json',timeoutMs=20000){
 const controller=new AbortController(),deadline=setTimeout(()=>controller.abort(),timeoutMs);
 try{
  const response=await fetch(url,{...options,signal:controller.signal});
  if(!response.ok){let message;try{message=(await response.json()).error;}catch{}throw new Error(message||(response.status===401?'Войдите в аккаунт ещё раз.':'Не удалось выполнить запрос.'));}
  if(read==='pdf'){
   if(!response.headers.get('content-type')?.includes('application/pdf'))throw new Error('Не удалось получить PDF. Попробуйте ещё раз.');
   const filename=response.headers.get('content-disposition')?.match(/filename\*=UTF-8''([^;]+)/i)?.[1];
   return {blob:await response.blob(),filename:filename?decodeURIComponent(filename):'resume.pdf'};
  }
  return await response.json();
 }catch(error){
  if(controller.signal.aborted)throw new Error(options.method==='POST'?'Сервер долго не отвечает. Не удалось подтвердить сохранение — проверьте кабинет перед повтором.':'Сервер долго не отвечает. Попробуйте ещё раз.');
  throw error;
 }finally{clearTimeout(deadline);}
}
async function api(body,returnState=false){return requestData('/api/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(returnState?{...body,returnState:true,stateRole:role,stateQuery:query,stateSelection:{...needContext,spec:needSpec,grade:needGrade,stack:needConfirmed?needStack:undefined,confirmed:needConfirmed}}:body)});}
async function refresh(){const revision=viewRevision,params=new URLSearchParams({role,query});if(query.trim()){for(const [key,value] of Object.entries(needContext))if(value)params.set(key,value);if(needSpec)params.set('spec',needSpec);if(needGrade)params.set('grade',needGrade);if(needConfirmed){params.set('stack',needStack);params.set('confirmed','1');}}const data=await requestData('/api/state?'+params,{cache:'no-store'});if(revision===viewRevision)state={...state,...data};}
async function mutate(body,next){
 if(busy)return;busy=true;
 const submit=overlay.querySelector('button[type="submit"]')||app.querySelector('form button[type="submit"]'),submitLabel=submit?.textContent;
 let committed=false;
 if(submit){submit.disabled=true;submit.textContent='Сохраняем…';submit.setAttribute('aria-busy','true');}
 try{
  const response=await api(body,true);
  committed=true;
  if(response.state){viewRevision++;state={...state,...response.state};}
  else await refresh();
  invalidateResumePDF();close();if(next)go(next);else render();
  if(response.message)toast(response.message);return response;
 }catch(e){const message=committed?'Изменения сохранены, но обновить страницу не удалось. Перезагрузите её перед повтором.':e.message;const error=overlay.querySelector('[data-error]')||app.querySelector('[data-error]');if(error){error.textContent=message;error.focus();}else toast(message);}
 finally{busy=false;if(submit){submit.disabled=false;submit.textContent=submitLabel;submit.removeAttribute('aria-busy');}}
}
function go(next){page=next;location.hash=next==='home'?'':next;close();render();window.scrollTo({top:0});}
function close(){overlay.innerHTML='';document.body.classList.remove('overlay-open');previousFocus?.focus?.();}
function modal(h,p,body,wide=false){previousFocus=document.activeElement;overlay.innerHTML=`<div class="overlay" data-backdrop><section class="modal ${wide?'wide-modal':''}" role="dialog" aria-modal="true" aria-label="${esc(h)}"><div class="modal-header"><div><h2>${h}</h2><p>${p}</p></div><button class="icon-button" data-action="close" aria-label="Закрыть">${icon('close')}</button></div>${body}</section></div>`;document.body.classList.add('overlay-open');overlay.querySelector('input,button,select')?.focus();}
const formEnd=(label='Сохранить')=>`<p class="form-error" data-error tabindex="-1" role="alert"></p><div class="modal-actions">${button('Отмена','close','',true)}<button class="button" type="submit">${label}</button></div>`;
async function loginApp(wanted=role,next='dashboard'){
 if(busy)return;busy=true;
 try{
  const data=await requestData('/api/session',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'login',role:wanted})});
  viewRevision++;role=wanted;localStorage.setItem('fsp-role',role);state={...emptyState(),...data};invalidateResumePDF();
  if(state.roles.includes(role))go(next);else{go('home');onboarding(role);}
 }catch(error){toast(error.message);}finally{busy=false;}
}
async function logoutApp(){
 if(busy)return;busy=true;
 try{
  const data=await requestData('/api/session',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'logout'})});
  viewRevision++;invalidateResumePDF();state={...emptyState(),...data};test=null;result=null;answers=[];query='';jobQuery='';needSpec='';needGrade='';needStack='';needConfirmed=false;compare=[];needContext=contextFields(null);contextDraft=null;activeNeed=null;go('home');toast('Вы вышли из аккаунта.');
 }catch(error){toast(error.message);}finally{busy=false;}
}
function ensureRole(wanted,next='dashboard'){role=wanted;localStorage.setItem('fsp-role',role);if(!state.authenticated){loginApp(wanted,next);return;}if(!state.roles.includes(wanted)){onboarding(wanted);return;}refresh().then(()=>go(next)).catch(e=>toast(e.message));}
function onboarding(wanted){role=wanted;localStorage.setItem('fsp-role',wanted);const p=state.profile||{};modal(wanted==='candidate'?'Создайте профиль кандидата':'Расскажите о компании','Вы уже вошли через ChatGPT. Email аккаунта подтверждается провайдером.',`<form id="onboard" data-role="${wanted}"><div class="stack">${field(wanted==='candidate'?'Имя и фамилия':'Название компании','name',wanted==='candidate'?p.name:'','text','required maxlength="100"')}${field('Город','city',p.city||'','text','required')}${wanted==='candidate'?`<div class="inline-note">${icon('shield')}После создания профиля заполните обязательную анкету: направление, предполагаемый уровень, профессиональные роли и мягкие навыки. Затем откроется тест.</div>`:`${field('Контакт для кандидатов','contact',state.user?.email||'','email','required')}${textarea('Чем занимается компания','description','','required minlength="20"')}` }<label class="check-row"><input name="consent" type="checkbox" required>Согласен на обработку данных профиля. <a href="#privacy" data-action="legal">Условия</a></label></div>${formEnd('Создать профиль')}</form>`);}
function confirmNeed(){const need=state.need||{};const specOptions=`<option value="">Выберите специализацию</option>${options(specs,needSpec||need.spec)}`;const gradeOptions=`<option value="">Выберите уровень</option>${options(grades,needGrade||need.grade)}`;const warning=need.missing?.length||need.ambiguous?.spec||need.ambiguous?.grade?'Не все параметры удалось определить однозначно. Выберите их вручную.':'Проверьте распознанные параметры перед построением выдачи.';const evidence=need.evidence?.length?`<div class="need-evidence"><strong>Почему система предложила эти параметры</strong>${need.evidence.map(item=>`<div><span>${esc(item.field)} · ${esc(item.value)}</span><q>${esc(item.quote)}</q></div>`).join('')}</div>`:'';modal('Подтвердите потребность',warning,`<form id="need-confirm-form"><div class="need-source"><span>Запрос работодателя</span><strong>${esc(query)}</strong></div>${evidence}<div class="form-row"><div class="field"><label for="confirmed-spec">Специализация</label><select id="confirmed-spec" name="spec" required>${specOptions}</select></div><div class="field"><label for="confirmed-grade">Уровень</label><select id="confirmed-grade" name="grade" required>${gradeOptions}</select></div></div>${field('Обязательные технологии','stack',needStack||(need.stack||[]).join(', '),'text','placeholder="Например: Python, PostgreSQL"')}<div class="inline-note">${icon('shield')}Система не подставляет специализацию или уровень по умолчанию. Подбор начнётся только после вашего подтверждения.</div>${formEnd('Показать кандидатов')}</form>`);}
function header(){const signed=state.authenticated,member=state.roles.includes(role);return `<header class="site-header"><div class="header-inner"><a class="brand" href="#home" data-action="nav" data-page="home"><span class="brand-icon">фсп</span><span>Карьера</span></a><nav class="public-nav" aria-label="Основная навигация"><a href="#jobs" data-action="nav" data-page="jobs">Вакансии</a><a href="#employers" data-action="nav" data-page="employers">Работодателям</a><a href="#method" data-action="nav" data-page="method">Как это работает</a></nav><div class="header-actions">${signed?`<button class="account-switch" data-action="switch-workspace">${icon(role==='employer'?'briefcase':'user','small-icon')}<span>${role==='employer'?'Работодатель':'Кандидат'}</span>${icon('down','small-icon')}</button>${button(member?'Мой кабинет':'Создать профиль',member?'nav':'join',member?'data-page="dashboard"':`data-role="${role}"`,true)}<button class="header-signout" data-action="logout" aria-label="Выйти из аккаунта">Выйти</button>`:`${button('Войти','login','',true)}${button('Создать резюме','join','data-role="candidate"')}`}</div></div></header>`;}
function nav(){if(!state.roles.includes(role)||['home','employers','method','privacy','help','onboarding-candidate','onboarding-employer'].includes(page))return '';const menus=role==='employer'?[['dashboard','Обзор'],['catalog','Поиск кандидатов'],['needs','Подборки'],['invites','Приглашения'],['jobs','Вакансии'],['applications','Отклики'],['tasks','Задания'],['company','Компания']]:[['dashboard','Обзор'],['profile','Моё резюме'],['survey','Анкета'],['tests','Подтверждение навыков'],['offers','Приглашения'],['jobs','Вакансии'],['applications','Мои отклики'],['tasks','Задания'],['settings','Настройки']];return `<nav class="product-nav" aria-label="Личный кабинет">${menus.map(([key,label])=>`<a href="#${key}" data-action="nav" data-page="${key}" class="nav-item ${page===key?'active':''}">${label}${(role==='employer'||state.privacy?.notifications)&&key===(role==='employer'?'invites':'offers')&&state.invites.filter(i=>i.status==='sent').length?`<span class="nav-count">${state.invites.filter(i=>i.status==='sent').length}</span>`:''}</a>`).join('')}</nav>`;}
function footer(){return `<footer class="site-footer"><div><a class="footer-brand" href="#home">ФСП Карьера</a><p>Работа в IT начинается с навыков.</p><small>MVP · достижения ФСП на тестовых данных</small></div><div><strong>Кандидатам</strong><a href="#jobs">Вакансии</a><a href="#tests" data-action="join" data-role="candidate">Подтвердить навыки</a><a href="#profile" data-action="join" data-role="candidate">Создать резюме</a></div><div><strong>Компаниям</strong><a href="#employers">Подбор специалистов</a><a href="#catalog" data-action="join" data-role="employer">Найти кандидата</a><a href="#company" data-action="join" data-role="employer">Профиль компании</a></div><div><strong>О сервисе</strong><a href="#method">Механика подбора</a><a href="#privacy">Данные и приватность</a><a href="#help">Помощь</a><a href="/openapi.json" target="_blank">API</a></div></footer>`;}
function home(){return `<section class="home-hero reverse-hero"><div class="hero-copy"><div class="eyebrow">Обратный найм в IT</div><h1>Работодатель<br>находит кандидата.</h1><p>Специалисты подтверждают категорию тестом. Компания описывает потребность, выбирает человека и первой предлагает роль с открытой зарплатой.</p><div class="hero-actions">${button('Найти специалиста','join','data-role="employer"')}${button('Создать профиль кандидата','join','data-role="candidate"',true)}</div></div><aside class="hero-board"><div class="board-top"><span>Подбор команды</span>${icon('search')}</div><div class="board-grade">92/100<br><span>соответствие потребности</span></div><div class="board-divider"></div><div class="board-line"><span>Категория</span><strong>Backend · Middle</strong></div><div class="board-offer"><span>Прямое приглашение</span><strong>180 000–250 000 ₽</strong><p>Контакт откроется после согласия</p></div><small>Выдача объясняет каждое совпадение</small></aside></section><section class="reverse-flow home-section"><div class="section-heading"><div><div class="eyebrow">Основной сценарий</div><h2>От потребности команды до принятого предложения</h2></div><a href="#method">Подробная механика ${icon('arrow','small-icon')}</a></div><ol>${[['Компания описывает потребность','Специализация, уровень и обязательные технологии подтверждаются перед поиском.'],['Система ранжирует кандидатов','Учитываются подтверждённая категория, тест, технологии и достижения ФСП.'],['Работодатель делает предложение','Конкретный кандидат получает задачи, компанию и зарплату до открытия контакта.'],['Кандидат принимает решение','Контакт открывается только выбранной компании после согласия кандидата.']].map(([h,p],i)=>`<li><span>0${i+1}</span><div><h3>${h}</h3><p>${p}</p></div></li>`).join('')}</ol></section><section class="entry-strip reverse-entry"><div><h2>Кандидат не соревнуется за внимание в ленте вакансий</h2><p>Он подтверждает навыки один раз и получает адресные предложения от заинтересованных команд.</p></div>${button('Подтвердить навыки '+icon('arrow','small-icon'),'join','data-role="candidate"')}</section><section class="employer-callout"><div><h2>Начните с потребности команды</h2><p>Вакансия не обязательна. Опишите специалиста, подтвердите распознанные параметры и получите объяснимую подборку.</p></div>${button('Перейти к подбору '+icon('arrow','small-icon'),'join','data-role="employer"',true)}</section><p class="secondary-path">Самостоятельные отклики остаются дополнительным способом знакомства. <a href="#jobs">Открыть вакансии</a></p>`;}
function employerHome(){return `<section class="employer-hero"><div class="eyebrow">Для работодателей</div><h1>Найдите тех,<br>кто умеет.</h1><p>Подбор IT-специалистов по подтверждённой категории. От запроса команды до приглашения конкретному человеку.</p><div class="hero-actions">${button('Найти специалиста','join','data-role="employer"')}${button('Как устроен подбор','nav','data-page="method"',true)}</div></section><div class="feature-columns">${[['Категория вместо догадок','Специализация и грейд присваиваются по результатам теста.'],['Понятная выдача','Видно, почему профиль попал в подборку и какие технологии совпали.'],['Прямое приглашение','Вакансия не обязательна. Опишите задачу, условия и зарплату.']].map(([h,p],i)=>`<article><span>0${i+1}</span><h2>${h}</h2><p>${p}</p></article>`).join('')}</div><section class="employer-example"><div><h2>Опишите, кто нужен команде</h2><p>Например: «Middle backend, Python и PostgreSQL, удалённо». Запрос превращается в категорию и объяснимую подборку.</p>${button('Создать кабинет компании','join','data-role="employer"')}</div><div class="example-search">${icon('search')}<strong>Middle · Backend · Python</strong><div><span>Специализация</span><b>Backend</b></div><div><span>Подтверждённый уровень</span><b>Middle</b></div><div><span>Совпадение технологий</span><b>Python, PostgreSQL</b></div><small>Пример запроса</small></div></section>`;}
function dashboard(){const p=state.profile,c=state.company,employer=role==='employer',surveyDone=state.surveys.length>0,pending=state.invites.filter(i=>['sent','viewed'].includes(i.status)),activity=pending.length?pending:state.invites;return `${title(employer?`Кабинет компании ${esc(c.name)}`:`${esc(p.name)}, ваш следующий шаг`,employer?'Потребности команды, кандидаты и актуальные статусы.':'Анкета, профиль, предложения и подтверждение навыков — всё под рукой.',button(employer?'Найти кандидатов':surveyDone?'Моё резюме':'Заполнить анкету','nav',`data-page="${employer?'catalog':surveyDone?'profile':'survey'}"`))}<div class="dashboard-grid"><section class="dashboard-main"><div class="dashboard-feature ${employer?'employer-feature':''}"><div class="eyebrow">${employer?'Подбор в команду':'Ваш профиль'}</div><h2>${employer?'Кто нужен вашей команде?':!surveyDone?'Начните с анкеты':p.verified?`${esc(p.spec)} · ${esc(p.grade)}`:'Подтвердите навыки и откройте новые возможности'}</h2><p>${employer?'Укажите специализацию, уровень и технологии. Система подберёт подтверждённые профили.':!surveyDone?'Выберите направление, профессиональные роли и мягкие навыки. По ответам система откроет подходящий тест.':p.verified?`Уровень подтверждён ${date(p.verifiedAt)}. ${state.privacy.visible&&state.privacy.consent?'Работодатели могут найти вас.':'Профиль скрыт из поиска.'}`:'Работодатели находят кандидатов по результатам тестирования, а не только по резюме.'}</p>${employer?`<form id="demand-form" class="dashboard-search"><input name="query" aria-label="Потребность команды" required placeholder="Middle backend, Python, PostgreSQL"><button class="button" type="submit">Подобрать</button></form>`:button(!surveyDone?'Заполнить анкету':p.verified?'Посмотреть историю тестов':'Пройти тест','nav',`data-page="${surveyDone?'tests':'survey'}"`)}</div><div class="dashboard-stats">${[[state.invites.length,employer?'Приглашений отправлено':'Приглашений получено'],[state.applications.length,employer?'Откликов на вакансии':'Ваших откликов'],[employer?state.jobs.filter(j=>j.own&&j.status==='published').length:state.tests.filter(t=>t.status==='finished').length,employer?'Открытых вакансий':'Завершённых тестов']].map(([n,s])=>`<div><strong>${n}</strong><span>${s}</span></div>`).join('')}</div><section class="panel dashboard-panel"><div class="section-heading"><h2>${employer?'Текущие приглашения':'Предложения от компаний'}</h2><a href="#${employer?'invites':'offers'}">Все предложения</a></div>${activity.length?activity.slice(0,3).map(i=>`<button class="activity-row" data-action="offer-detail" data-id="${i.id}"><span class="activity-icon">${icon('mail')}</span><div><strong>${esc(employer?i.candidateName:i.company)}</strong><p>${esc(i.title)} · ${salary(i.min,i.max)}</p></div>${status(i.status)}</button>`).join(''):empty(employer?'Приглашений пока нет':'Здесь появятся приглашения',employer?'Начните с потребности команды и предложите условия подходящему кандидату.':'Заполните профиль и подтвердите навыки. Работодатели смогут найти вас.')}</section></section><aside class="dashboard-side"><section class="panel"><h3>${employer?'Настройте кабинет':'Готовность профиля'}</h3><div class="checklist">${(employer?[[!!c.name,'Название компании'],[!!c.description,'Описание команды'],[!!c.contact,'Контакт для кандидатов']]:[[surveyDone,'Заполните анкету'],[!!p.about,'Расскажите о себе'],[p.stack.length>0,'Добавьте технологии'],[p.verified,'Подтвердите категорию'],[state.privacy.consent&&state.privacy.visible,'Разрешите поиск профиля']]).map(([done,label])=>`<div class="${done?'done':''}">${icon(done?'checkCircle':'clock','small-icon')}<span>${label}</span></div>`).join('')}</div>${button(employer?'Редактировать компанию':surveyDone?'Заполнить резюме':'Перейти к анкете','nav',`data-page="${employer?'company':surveyDone?'profile':'survey'}"`,true)}</section><section class="panel"><div class="eyebrow">Живые навыки</div><h3>Короткие задания от команд</h3><p class="subtext">${employer?'Предложите небольшую практическую задачу и получите свежий сигнал о навыках.':'Опишите подход к задаче компании и получите обратную связь.'}</p>${button(employer?'Создать задание':'Открыть задания','nav','data-page="tasks"',true)}</section><section class="help-note">${icon('shield')}<p>История ФСП не требуется. Подбор работает по результатам тестирования.</p></section></aside></div>`;}

function fspAchievements(fsp){return `<div class="fsp-achievements">${fsp.achievements.map(a=>`<div class="fsp-achievement">${icon('trophy','small-icon')}<div><strong>${esc(a.result)} · ${a.year}</strong><p>${esc(a.event)}</p><small>${esc(a.discipline)} · ${esc(a.format)} зачёт</small></div></div>`).join('')}</div>`;}
function fspSection(fsp,own=false){return `<section class="${own?'panel resume-section':'detail-section'} fsp-section"><div class="fsp-heading"><h${own?'2':'3'}>Достижения ФСП</h${own?'2':'3'}>${fsp?badge('Тестовые данные'):''}</div>${fsp?`<p class="fsp-id">ФСП ID <strong>${esc(fsp.id)}</strong></p>${fsp.achievements.length?fspAchievements(fsp):'<p class="subtext">В этом тестовом профиле пока нет достижений.</p>'}<p class="fsp-disclaimer">Демонстрационная история. Реальный реестр ФСП ещё не подключён.</p>`:'<p class="subtext">Добавьте историю соревнований к своему профессиональному опыту. Участие в ФСП необязательно.</p>'}${own?'<p class="subtext fsp-ranking-note">В подборе достижения поднимают резюме внутри категории — до 10 баллов из 100. Без истории профиль остаётся в поиске, скрытая история не учитывается.</p>':''}${own?button(fsp?'Управлять ФСП ID':'Привязать ФСП ID','fsp-manage','',true):''}</section>`;}
function fspManage(){const fsp=state.profile.fsp;modal('Связь с ФСП ID','Подключение реального реестра отложено. Сейчас можно проверить сценарий на тестовых данных.',`<form id="fsp-form"><div class="stack">${fsp?`<p>Текущий ID: <strong>${esc(fsp.id)}</strong> ${badge('Тестовые данные')}</p>`:''}${field('Тестовый ФСП ID','fspId',fsp?.id||'DEMO-FSP-001','text','required maxlength="40" aria-describedby="fsp-examples"')}<p id="fsp-examples" class="subtext">DEMO-FSP-001 — финалист, DEMO-FSP-003 — призёр, DEMO-FSP-004 — без достижений, DEMO-FSP-011 — два результата прошлых лет. Доступны ID от 001 до 014.</p><div class="inline-note">${icon('document')}Это синтетические примеры для проверки MVP. Настоящий ФСП ID и проверка владения аккаунтом появятся при подключении реестра.</div>${fsp?button('Отвязать тестовый ID','fsp-unlink','type="button"',true):''}</div>${formEnd(fsp?'Обновить тестовую привязку':'Привязать тестовый ID')}</form>`);}

// Employer matching views. The server splits every score into named parts; the client only lays them out.
const plural=(n,one,few,many)=>`${n} ${n%10===1&&n%100!==11?one:n%10>=2&&n%10<=4&&(n%100<10||n%100>=20)?few:many}`;
const budgetLabel=b=>b.budgetMin&&b.budgetMax?salary(b.budgetMin,b.budgetMax):b.budgetMin?`от ${money(b.budgetMin)} ₽`:`до ${money(b.budgetMax)} ₽`;
const contextFields=c=>({team:c?.team||'',format:c?.format||'',city:c?.city||'',budgetMin:c?.budgetMin?String(c.budgetMin):'',budgetMax:c?.budgetMax?String(c.budgetMax):''});
const scoreGroups=[['category','Категория'],['stack','Стек'],['test','Тест'],['fsp','ФСП'],['context','Контекст команды']];
const sourceLabel={test:'Тест',resume:'Резюме',fsp:'ФСП · тестовые данные'},relationLabel={exact:'Точное совпадение',higher:'Грейд выше',lower:'Грейд ниже',adjacent:'Смежное направление'},levelLabel={winner:'победа',prize:'призовое место',final:'финал',participant:'участие'};
function scoreBar(m,total){const groups=scoreGroups.map(([group,label])=>[group,label,m.parts.filter(p=>p.group===group).reduce((sum,p)=>sum+p.points,0)]).filter(([,,points])=>points);return `<div class="score-bar" role="img" aria-label="${groups.map(([,label,points])=>label+': '+points).join(', ')} из ${total}">${groups.map(([group,label,points])=>`<span class="score-${group}" style="width:${points/total*100}%" title="${label}: ${points}"></span>`).join('')}</div>`;}
function needSummary(n){const chips=[[n.spec,!n.spec?'уточните специализацию':n.confirmed?'подтверждено работодателем':n.evidence.specSource==='team'?'по описанию команды':'по словам: '+n.evidence.spec.slice(0,3).join(', ')],[n.grade,!n.grade?'уточните уровень':n.confirmed?'подтверждено работодателем':'по «'+n.evidence.grade+'»'],...(n.stack.length?[[n.stack.join(' · '),n.evidence.teamStack.length?'включая описание команды':'технологии']]:[]),...(n.format?[[n.format+(n.city&&n.format!=='Удалённо'?', '+n.city:''),'формат работы']]:[]),...(n.budgetMin||n.budgetMax?[[budgetLabel(n),n.evidence.budget==='text'?'бюджет из запроса':'бюджет']]:[]),...n.domains.map(d=>[d.label,'предметная область'])];return `<section class="need-summary" aria-label="Разбор потребности"><div class="need-summary-head"><span class="eyebrow">Разбор потребности</span><small>Правила на ключевых словах, не нейросеть</small></div><div class="need-chips">${chips.map(([value,hint])=>`<span class="need-chip"><strong>${esc(value)}</strong><small>${esc(hint)}</small></span>`).join('')}</div>${!n.confirmed&&n.defaulted.spec?'<p class="need-warning">Проверьте и подтвердите категорию. Уточните запрос, например «Frontend React» или «QA автотесты».</p>':''}</section>`;}
function teamContextForm(){const c=contextDraft||needContext,filled=Object.values(c).filter(Boolean).length;return `<details class="team-context" ${contextOpen??filled?'open':''}><summary>${icon('users','small-icon')}<span>Контекст команды</span>${filled?badge(plural(filled,'поле','поля','полей')):'<small>необязательно</small>'}</summary><div class="team-context-body"><div class="field team-field"><label for="f-team">Чем занимается команда</label><textarea id="f-team" name="team" form="demand-form" maxlength="2000" placeholder="Например: платёжный сервис для малого бизнеса, высокая нагрузка, интеграции с банками">${esc(c.team)}</textarea></div><div class="field"><label for="f-need-format">Формат работы</label><select id="f-need-format" name="format" form="demand-form"><option value="">Любой</option>${options(['Удалённо','Гибрид','Офис'],c.format)}</select></div><div class="field"><label for="f-need-city">Город офиса</label><input id="f-need-city" name="city" form="demand-form" maxlength="80" value="${esc(c.city)}"></div>${field('Бюджет от, ₽','budgetMin',c.budgetMin,'number','form="demand-form" min="1" max="10000000"')}${field('Бюджет до, ₽','budgetMax',c.budgetMax,'number','form="demand-form" min="1" max="10000000"')}<p class="subtext team-context-note">Категорию задаёт запрос. Контекст уточняет порядок внутри неё: формат, бюджет и опыт в предметной области — до 10 баллов из 100. Технологии из описания добавятся к запросу.${filled?` <button class="text-button" type="button" data-action="clear-context">Очистить контекст</button>`:''}</p></div></details>`;}
function categoryStrip(){const items=state.categories||[],n=state.need;if(!items.length)return '';const active=c=>filter.spec===c.spec&&filter.grade===c.grade,heading=n?'Рекомендуемые категории':'Категории в банке кандидатов';return `<section class="category-strip" aria-label="${heading}"><div class="category-strip-head"><h2>${heading}</h2>${filter.spec!=='all'||filter.grade!=='all'?'<button class="text-button" data-action="category" data-spec="all" data-grade="all">Все категории</button>':''}</div><div class="category-grid ${n?'':'compact'}">${items.map(c=>`<button class="category-card ${active(c)?'active':''}" data-action="category" data-spec="${esc(c.spec)}" data-grade="${esc(c.grade)}" aria-pressed="${active(c)}">${n?`<span class="category-relation relation-${c.relation}">${relationLabel[c.relation]}</span>`:''}<strong>${esc(c.spec)} · ${esc(c.grade)}</strong><span class="category-count">${plural(c.count,'кандидат','кандидата','кандидатов')}${c.withFsp?` · ${c.withFsp} с ФСП`:''}</span>${c.salary?`<span class="category-salary">${Math.round(c.salary.min/1000)}–${Math.round(c.salary.max/1000)} тыс. ₽${c.inBudget!=null?` · в бюджете ${c.inBudget}`:''}</span>`:''}${c.reason?`<small>${esc(c.reason)}</small>`:''}</button>`).join('')}</div></section>`;}
const snapshotIds=()=>activeNeed?.snapshot&&state.need?new Set(activeNeed.snapshot.items.map(item=>item.id)):null;
const isFresh=c=>c.match.relation==='exact'&&!!snapshotIds()&&activeNeed.snapshot.items.length===activeNeed.snapshot.total&&!snapshotIds().has(c.id);
function snapshotNote(){const ids=snapshotIds();if(!ids)return '';if(activeNeed.snapshot.items.length<activeNeed.snapshot.total)return `<div class="snapshot-note">Сохранённая подборка содержит неполный исторический снимок. Сохраните поиск заново для сравнения изменений.</div>`;const current=state.candidates.filter(c=>c.match.relation==='exact'),fresh=current.filter(c=>!ids.has(c.id)).length,gone=[...ids].filter(id=>!current.some(c=>c.id===id)).length;return `<div class="snapshot-note">${icon('clock','small-icon')}<span>Подборка «${esc(activeNeed.title)}» сохранена ${date(activeNeed.snapshot.at)}: ${plural(activeNeed.snapshot.total,'кандидат','кандидата','кандидатов')} в категории ${esc(activeNeed.spec)} · ${esc(activeNeed.grade)}. Сейчас — ${current.length}${fresh?`, новых ${fresh}`:''}${gone?`, выбыли ${gone}`:''}.</span></div>`;}
function matchBreakdown(m,heading,total){return `<section class="match-explanation"><h3>${heading}</h3>${scoreBar(m,total)}<div class="table-wrap"><table class="data-table match-table"><thead><tr><th>Признак</th><th>Основание</th><th>Баллы</th></tr></thead><tbody>${m.parts.map(p=>`<tr><td><span class="score-dot score-${p.group}" aria-hidden="true"></span>${esc(p.label)}<small>${sourceLabel[p.source]}</small></td><td>${esc(p.note)}</td><td>${p.points}/${p.max}</td></tr>`).join('')}</tbody></table></div>${m.fsp?.items.length?`<div class="fsp-contribution"><strong>Вклад ФСП: +${m.fsp.points} из 10 · тестовые данные</strong><ul>${m.fsp.items.map(i=>`<li>${esc(i.result)} · ${esc(i.event)}, ${i.year}: ${levelLabel[i.level]||'участие'}, профильность ${Math.round(i.relevance*100)}%, давность ${Math.round(i.recency*100)}%</li>`).join('')}</ul><p>Лучший результат учитывается полностью, каждый следующий добавляет 10%. Отсутствие истории не снижает остальные баллы.</p></div>`:''}<small>Категория и результат теста подтверждены сервером; технологии, формат, ожидания и опыт заявлены кандидатом. Веса — гипотеза MVP до калибровки на размеченных парах.</small></section>`;}
// Keep an unsent team description across re-renders caused by filters or favourites.
document.addEventListener('input',e=>{if(e.target.closest?.('.team-context'))contextDraft={...(contextDraft||needContext),[e.target.name]:e.target.value};});
document.addEventListener('toggle',e=>{if(e.target.classList?.contains('team-context'))contextOpen=e.target.open;},true);
function candidateCard(c){const m=c.match,best=m.fsp?.items[0],matched=(m.matched||[]).map(x=>x.toLowerCase());return `<article class="candidate-card"><div class="resume-topline"><span>${icon('shield','small-icon')}Категория подтверждена ${c.synthetic?'· демопрофиль':''}${isFresh(c)?' '+badge('Новый в подборке','green'):''}</span><button class="icon-button ${state.favorites.includes(c.id)?'saved':''}" data-action="favorite" data-id="${c.id}" aria-label="Сохранить ${esc(c.name)}" aria-pressed="${state.favorites.includes(c.id)}">${icon('heart')}</button></div><h2 class="resume-position"><button data-action="candidate-detail" data-id="${c.id}">${esc(titles[c.spec])}</button></h2><div class="resume-compensation"><span>${salary(c.min,c.max)}</span><small>в месяц</small><span class="experience-chip">Опыт ${esc(c.experience)}</span></div><div class="resume-person"><button data-action="candidate-detail" data-id="${c.id}">${esc(c.name)}</button><span class="verified-label">${icon('checkCircle','small-icon')}${esc(c.grade)} подтверждён</span></div><div class="resume-meta">${esc(c.city)} · ${esc(c.format||'Удалённо')}</div><div class="resume-proof"><span>Тест <strong>${c.score}/100</strong></span>${c.stack.map(s=>`<span class="${matched.includes(s.toLowerCase())?'matched':''}">${esc(s)}</span>`).join('')}</div>${best?`<div class="fsp-card-proof">${icon('trophy','small-icon')}<span>${esc(best.result)} ФСП · ${best.year}${m.fsp.points?` · <b>+${m.fsp.points} к рейтингу</b>`:''}</span><small>Тестовые данные</small></div>`:''}<div class="resume-match">${scoreBar(m,m.score===null?30:100)}<span>${esc(m.reasons.filter((r,i)=>!(i===0&&m.relation==='exact')&&!/^(Тест|ФСП) /.test(r)).slice(0,3).join(' · '))}</span><span class="match-score">${m.score===null?`Сила профиля ${m.strength}/30`:`${m.score}/100 по запросу`}</span></div><div class="resume-actions">${button('Пригласить','invite','data-id="'+c.id+'"')}${button('Посмотреть профиль','candidate-detail','data-id="'+c.id+'"',true)}${button(compare.includes(c.id)?'Убрать из сравнения':'Сравнить','compare-candidate','data-id="'+c.id+'"',true)}<span>${icon(c.email?'check':'lock','small-icon')}${c.email?'Контакт открыт':'Контакты после согласия'}</span></div></article>`;}
function filteredCandidates(){let data=state.candidates.filter(c=>(filter.spec==='all'||c.spec===filter.spec)&&(filter.grade==='all'||c.grade===filter.grade)&&(filter.format==='all'||c.format===filter.format)&&(filter.fsp==='all'||(filter.fsp==='with'?c.fsp?.achievements.length:!c.fsp?.achievements.length))&&filter.stack.split(',').map(s=>s.trim().toLowerCase()).filter(Boolean).every(s=>c.stack.some(t=>t.toLowerCase().includes(s))));if(filter.sort==='salary')data.sort((a,b)=>a.min-b.min);if(filter.sort==='score')data.sort((a,b)=>b.score-a.score);if(filter.sort==='strength')data.sort((a,b)=>b.match.strength-a.match.strength||b.score-a.score);if(filter.sort==='favorites')data=data.filter(c=>state.favorites.includes(c.id));return data;}
function catalogPage(){const rows=filteredCandidates(),category=filter.spec!=='all'&&filter.grade!=='all'?` · ${esc(filter.spec)} · ${esc(filter.grade)}`:'';return `<section class="marketplace-search"><form id="demand-form" class="marketplace-search-form"><div class="marketplace-query"><label class="sr-only" for="need-query">Потребность команды</label><input id="need-query" name="query" value="${esc(query)}" placeholder="Нужен Middle backend: Python, PostgreSQL"></div>${button('Сохранить поиск','save-need','',true)}<button class="button" type="submit">Найти</button></form>${teamContextForm()}<div class="quick-filter-bar"><select data-filter="spec" aria-label="Специализация">${options(specs,filter.spec,'Специализация')}</select><select data-filter="grade" aria-label="Грейд">${options(grades,filter.grade,'Грейд')}</select><button class="filter-control" data-action="filters">${icon('plus','small-icon')}Технологии ${filter.stack?badge(filter.stack):''}</button><select data-filter="fsp" aria-label="Достижения ФСП"><option value="all" ${filter.fsp==='all'?'selected':''}>Достижения ФСП</option><option value="with" ${filter.fsp==='with'?'selected':''}>Есть достижения ФСП</option><option value="without" ${filter.fsp==='without'?'selected':''}>Без достижений ФСП</option></select><button class="filter-control all-filter-button" data-action="filters">Фильтры ${icon('settings','small-icon')}</button></div></section>${state.need?needSummary(state.need)+button(state.need.confirmed?'Изменить категорию':'Подтвердить категорию','edit-need','',true):''}${categoryStrip()}${snapshotNote()}${compare.length?`<div class="compare-tray"><span>Для сравнения: ${compare.length}</span>${button('Сравнить профили','open-comparison','',true)}${button('Очистить','clear-comparison','',true)}</div>`:''}<div class="results-heading"><h1>Найдено ${plural(rows.length,'IT-специалист','IT-специалиста','IT-специалистов')}${category}</h1><button class="text-button" data-action="nav" data-page="method">Как работает подбор ${icon('document','small-icon')}</button></div><div class="results-toolbar"><select data-filter="sort" aria-label="Сортировка"><option value="match" ${filter.sort==='match'?'selected':''}>По соответствию</option><option value="strength" ${filter.sort==='strength'?'selected':''}>По силе профиля: тест и ФСП</option><option value="score" ${filter.sort==='score'?'selected':''}>По результатам теста</option><option value="salary" ${filter.sort==='salary'?'selected':''}>По зарплате</option><option value="favorites" ${filter.sort==='favorites'?'selected':''}>Только избранное</option></select><span>${query?'Запрос: '+esc(query):'Подтверждённые категории · без запроса порядок задаёт сила профиля'}</span></div><div class="score-legend" aria-hidden="true">${(state.need?scoreGroups:scoreGroups.filter(([group])=>['test','fsp'].includes(group))).map(([group,label])=>`<span><i class="score-dot score-${group}"></i>${label}</span>`).join('')}</div><div class="corpus-note">${icon('document','small-icon')}В каталоге ${state.candidates.filter(c=>c.synthetic).length} демонстрационных профилей. Реальные профили появляются после тестирования и согласия.</div>${rows.length?`<div class="candidate-grid">${rows.map(candidateCard).join('')}</div>`:empty('Пока нет совпадений','Сохранённый запрос остаётся доступен. Попробуйте расширить фильтры.',button('Сбросить фильтры','reset-filters'))}`;}
function jobCard(j){const applied=state.applications.some(a=>a.jobId===j.id);return `<article class="job-card"><div class="job-company"><span class="company-symbol">${esc(j.company.slice(0,1))}</span><strong>${esc(j.company)}</strong>${j.synthetic?badge('Демовакансия'):''}${j.own?status(j.status):''}</div><h2 class="job-title"><button data-action="job-detail" data-id="${j.id}">${esc(j.title)}</button></h2><div class="job-salary">${salary(j.min,j.max)} <small>в месяц</small></div><div class="job-meta">${esc(j.city||'Россия')} · ${esc(j.format)} · ${esc(j.grade)}</div>${tag(j.stack)}<p class="job-description">${esc(j.description.slice(0,220))}${j.description.length>220?'…':''}</p><div class="job-actions">${role==='employer'&&j.own?`${button('Редактировать','edit-job','data-id="'+j.id+'"')}${button(j.status==='published'?'В архив':'Опубликовать','job-status',`data-id="${j.id}" data-status="${j.status==='published'?'archived':'published'}"`,true)}`:`${button(applied?'Вы откликнулись':'Откликнуться',applied?'nav':'apply',applied?'data-page="applications"':`data-id="${j.id}"`,applied)}${button('Подробнее','job-detail',`data-id="${j.id}"`,true)}`}</div></article>`;}
function jobsPage(){const own=role==='employer'&&state.roles.includes('employer');const rows=state.jobs.filter(j=>(!own||j.own)&&(own||j.status==='published')&&(filter.spec==='all'||j.spec===filter.spec)&&`${j.title} ${j.company} ${j.stack.join(' ')}`.toLowerCase().includes(jobQuery.toLowerCase()));return `${title(own?'Вакансии компании':'Работа в IT',own?'Управляйте публикациями и смотрите отклики.':'Условия и зарплата известны до отправки отклика.',own?button('Опубликовать вакансию','new-job'):'' )}<form id="job-search-form" class="job-search"><input name="query" aria-label="Поиск вакансий" placeholder="Должность, компания или технология" value="${esc(jobQuery)}"><select name="spec" aria-label="Направление">${options(specs,filter.spec,'Все направления')}</select><button class="button">Найти</button></form><p class="result-count">${rows.length} вакансий</p>${rows.length?`<div class="job-grid">${rows.map(jobCard).join('')}</div>`:empty(own?'Открытых вакансий пока нет':'Ничего не найдено',own?'Приглашать кандидатов можно и без вакансии. Для самостоятельных откликов опубликуйте предложение.':'Попробуйте другую технологию или направление.',own?button('Создать вакансию','new-job'):button('Сбросить поиск','reset-jobs'))}`;}
function profilePage(){const p=state.profile,latest=state.tests.find(t=>t.result),weak=latest?.result?.feedback?.filter(x=>!x.correct)||[];return `${title('Моё резюме','Редактируйте поля резюме и скачивайте готовый PDF из сохранённых данных.',`<div class="resume-title-actions">${button('Редактировать резюме','edit-profile','',true)}${button('Скачать PDF','pdf')}</div>`)}<div class="profile-layout"><section><article class="panel resume-summary"><div class="profile-avatar">${esc(initials(p.name))}</div><div><h2>${esc(p.name)}</h2><p>${[p.city,p.format].filter(Boolean).map(esc).join(' · ')}</p>${p.verified?badge(p.spec+' · '+p.grade+' подтверждён','green'):badge('Категория не подтверждена')}</div></article><article class="panel resume-section"><h2>Желаемая работа</h2><h3>${esc(titles[p.spec])}</h3><strong class="profile-salary">${salary(p.min,p.max)}</strong><p>${[p.experience?'Опыт: '+esc(p.experience):'',esc(p.format)].filter(Boolean).join(' · ')}</p>${tag(p.stack)}</article><article class="panel resume-section"><h2>О себе</h2><p class="multiline">${esc(p.about||'Добавьте описание — какой опыт у вас есть и какие задачи интересны.')}</p>${historyProfileSection('workEntries')}${historyProfileSection('educationEntries')}</article>${resumeExtraSections()}${weak.length?`<article class="panel resume-section development-plan"><h2>Следующий шаг в развитии</h2><p>План сформирован по последней попытке и не влияет на подтверждённую категорию.</p>${weak.map((item,index)=>`<div><span>${index+1}</span><div><strong>${esc(item.topic)}</strong><p>${esc(item.explanation)} Затем закрепите тему короткой практической задачей.</p></div></div>`).join('')}</article>`:''}<section class="panel resume-section competency-passport"><h2>Паспорт компетенций</h2>${p.competencies?.length?`<div class="competency-grid">${p.competencies.map(item=>`<div class="competency ${item.status}"><strong>${esc(item.name)}</strong><span>${item.status==='confirmed'?'Подтверждено тестом':'Зона развития'}</span><small>${esc(item.source)} · ${date(item.verifiedAt)}</small></div>`).join('')}</div>`:'<p class="subtext">Компетенции появятся после принятого результата теста.</p>'}${p.roles?.length?`<h3>Профессиональные роли</h3>${tag(p.roles)}`:''}${p.softSkills?.length?`<h3>Мягкие навыки — самооценка из анкеты</h3>${tag(p.softSkills)}`:''}${button('Открыть анкету','nav','data-page="survey"',true)}</section>${fspSection(p.fsp,true)}<article class="panel resume-section"><h2>Контактные данные</h2><p>${esc(state.user.email)}${p.phone?' · '+esc(p.phone):''}</p><div class="inline-note">${icon('lock')}Другие кандидаты не видят резюме. Компания получает контакт только после принятия её приглашения или вашего отклика.</div></article></section><aside><section class="panel resume-section"><h3>Видимость профиля</h3><p>${state.privacy.visible&&state.privacy.consent&&p.verified?'Доступен в поиске работодателей.':'Пока не доступен в поиске.'}</p>${button('Настроить приватность','nav','data-page="settings"',true)}</section><section class="panel resume-section"><h3>Подтверждённая категория</h3><p>${p.verified?esc(p.spec+' / '+p.grade)+' · '+p.score+'/100':'Выберите уровень и пройдите тест.'}</p><small>${p.verified?'Последняя проверка: '+date(p.verifiedAt):'Самооценка не подтверждает уровень.'}</small>${button(p.verified?'История и повторный тест':'Пройти тест','nav','data-page="tests"',true)}</section><section class="panel resume-section"><h3>История соревнований</h3><p>Достижения дополняют резюме. Категория подтверждается тестом и доступна без участия в ФСП.</p><small>Подключение реестра — следующий этап.</small></section></aside></div>`;}
function surveyPage(){const p=state.profile,latest=state.surveys[0]||{},current=(key,fallback='')=>latest[key]??fallback;return `${title('Анкета кандидата','Расскажите о профессиональном опыте, сильных сторонах и условиях, в которых вы работаете лучше всего.')}<div class="survey-intro panel"><div><span class="survey-kicker">Перед подтверждением навыков</span><h2>${state.surveys.length?'Обновите карьерный профиль':'Заполните карьерный профиль'}</h2><p>Ответы определяют категорию теста и помогают работодателю оценить не только технологии, но и подходящий формат команды. Обычно это занимает 7–10 минут.</p></div><div class="survey-progress"><strong>${state.surveys.length?'Версия '+(latest.version||state.surveys.length):'Новая анкета'}</strong><span>5 содержательных разделов</span></div></div><div class="survey-layout"><form id="survey-form" class="survey-form"><fieldset id="survey-goal" class="panel survey-card"><legend><span>1</span><div><strong>Карьерная ситуация</strong><small>Что вы ищете сейчас</small></div></legend><div class="survey-question"><h3>Главная карьерная цель</h3>${radioGrid('careerGoal',careerGoals,current('careerGoal','Сменить компанию'))}</div><div class="form-row">${select('Текущая ситуация','employmentStatus',employmentStatuses,current('employmentStatus','Работаю, открыт к предложениям'))}${select('Коммерческий опыт','experienceYears',experienceRanges,current('experienceYears',p.experience||'1–3 года'))}</div></fieldset><fieldset id="survey-direction" class="panel survey-card"><legend><span>2</span><div><strong>Направление и роли</strong><small>Какую категорию будем подтверждать</small></div></legend><div class="form-row">${select('Отрасль или тип продукта','industry',industries,current('industry','Финтех'))}${select('Основная специализация','spec',specs,current('spec',p.surveySpec||p.spec||'Backend'))}</div><div class="form-row">${select('Предполагаемый уровень','grade',grades,current('grade',p.surveyGrade||p.grade||'Middle'))}${select('Основная роль','primaryRole',professionalRoles,current('primaryRole',current('roles',[])[0]||'Разработчик'))}</div><div class="survey-question"><h3>Дополнительные профессиональные роли</h3><p>Выберите всё, что отражает ваш опыт или желаемую траекторию.</p>${choiceGrid('roles',professionalRoles,current('roles',p.roles||[]))}</div>${textarea('Ключевые технологии и инструменты','technicalSkills',current('technicalSkills',p.stack?.join(', ')||''),'required minlength="3" maxlength="600" placeholder="Например: Python, FastAPI, PostgreSQL, Docker"')}${textarea('Самый показательный профессиональный результат','achievement',current('achievement',''),'required minlength="30" maxlength="1200" placeholder="Опишите задачу, свои действия и измеримый результат"')}</fieldset><fieldset id="survey-soft" class="panel survey-card"><legend><span>3</span><div><strong>Мягкие навыки</strong><small>Не просто список качеств, а примеры поведения</small></div></legend><div class="survey-question"><h3>Ваши сильные стороны</h3><p>Выберите от двух до пяти навыков, которые можете подтвердить конкретной ситуацией.</p>${choiceGrid('softSkills',softSkillOptions,current('softSkills',p.softSkills||[]))}</div>${textarea('Пример совместной работы или сложной коммуникации','softSkillExample',current('softSkillExample',''),'required minlength="40" maxlength="1200" placeholder="Какая была ситуация, что сделали лично вы и к чему это привело"')}<div class="survey-question"><h3>Если задача поставлена неоднозначно, вы обычно…</h3>${radioGrid('uncertaintyResponse',['Сначала уточняю цель и ограничения','Предлагаю несколько вариантов и сверяю направление','Начинаю с небольшого проверяемого шага','Самостоятельно принимаю решение и сообщаю команде'],current('uncertaintyResponse','Предлагаю несколько вариантов и сверяю направление'))}</div><div class="survey-question"><h3>Как вы предпочитаете получать обратную связь?</h3>${radioGrid('feedbackPreference',['Сразу по ходу работы','На регулярных встречах один на один','Письменно с конкретными примерами','Формат не важен, важна конкретика'],current('feedbackPreference','Формат не важен, важна конкретика'))}</div></fieldset><fieldset id="survey-work" class="panel survey-card"><legend><span>4</span><div><strong>Условия работы</strong><small>Среда, в которой вы будете эффективнее</small></div></legend><div class="form-row">${select('Предпочтительный формат','preferredFormat',['Удалённо','Гибрид','Офис'],current('preferredFormat',p.format||'Удалённо'))}${select('Организация работы','workStyle',['Команда','Самостоятельно','Смешанный формат'],current('workStyle','Смешанный формат'))}</div><div class="form-row">${select('Размер команды','teamSize',['До 5 человек','6–10 человек','11–25 человек','Не принципиально'],current('teamSize','6–10 человек'))}${select('Предпочтительный тип задач','taskType',['Новый продукт с нуля','Развитие работающего продукта','Исследования и прототипы','Стабильность и инфраструктура','Не принципиально'],current('taskType','Развитие работающего продукта'))}</div><div class="form-row">${select('Готовность к командировкам','businessTrips',['Не готов','Редкие командировки','Готов регулярно'],current('businessTrips','Редкие командировки'))}${select('Готовность к переезду','relocation',['Не рассматриваю','Готов обсудить','Готов к переезду'],current('relocation','Готов обсудить'))}</div></fieldset><fieldset id="survey-motivation" class="panel survey-card"><legend><span>5</span><div><strong>Мотивация и ожидания</strong><small>Что важно при выборе предложения</small></div></legend>${textarea('Что важно в следующей роли','motivation',current('motivation',''),'required minlength="40" maxlength="1200" placeholder="Например: влияние на продукт, сильная команда, понятная зона ответственности, рост"')}${textarea('Какие задачи вы точно не хотели бы выполнять','avoidTasks',current('avoidTasks',''),'maxlength="800" placeholder="Необязательно, но помогает исключить неподходящие предложения"')}<label class="survey-confirm"><input type="checkbox" name="answersConfirmed" required><span>Я проверил ответы. Понимаю, что специализация и предполагаемый уровень определят категорию следующего теста.</span></label><p class="form-error" data-error role="alert"></p><div class="survey-submit"><div><strong>Сохранится новая версия</strong><span>Предыдущие ответы останутся в истории</span></div><button class="button" type="submit">Сохранить и перейти к тесту</button></div></fieldset></form><aside class="survey-aside"><nav class="panel survey-index" aria-label="Разделы анкеты"><h3>Разделы анкеты</h3>${[['survey-goal','Карьерная ситуация'],['survey-direction','Направление и роли'],['survey-soft','Мягкие навыки'],['survey-work','Условия работы'],['survey-motivation','Мотивация']].map(([target,label],index)=>`<button data-action="survey-section" data-target="${target}"><span>${index+1}</span>${label}</button>`).join('')}</nav><section class="panel survey-summary"><h3>Как используются ответы</h3><p>Специализация и предполагаемый уровень задают тест. Роли, опыт, сильные стороны и рабочие предпочтения дополняют резюме работодателя.</p><div class="inline-note">${icon('shield')}Ответы видны только в вашем профиле и компаниям, которым доступно резюме.</div></section></aside></div><section class="history-panel"><div class="section-heading"><div><h2>История анкет</h2><p>Каждая версия хранится отдельно — можно увидеть, как менялись цели и предпочтения.</p></div></div>${state.surveys.length?`<div class="survey-history-list">${state.surveys.map(s=>`<details class="panel survey-history-item"><summary><div><strong>Версия ${s.version}</strong><span>${date(s.created)} · ${esc(s.spec)} / ${esc(s.grade)}</span></div>${badge(s.careerGoal||s.industry)}</summary><div class="survey-history-content"><dl><div><dt>Карьерная цель</dt><dd>${esc(s.careerGoal||'Не указана')}</dd></div><div><dt>Роли</dt><dd>${esc((s.roles||[]).join(', '))}</dd></div><div><dt>Мягкие навыки</dt><dd>${esc((s.softSkills||[]).join(', '))}</dd></div><div><dt>Формат</dt><dd>${esc(s.preferredFormat||'Не указан')} · ${esc(s.workStyle||'')}</dd></div></dl><p><strong>Мотивация:</strong> ${esc(s.motivation||'Не указана')}</p></div></details>`).join('')}</div>`:empty('Анкета ещё не заполнена','После сохранения здесь появится первая версия.')}</section>`;}
function testsPage(){const p=state.profile;if(!state.surveys.length)return `${title('Подтверждение навыков','Сначала заполните обязательную анкету кандидата.')}<section class="panel survey-required">${icon('document')}<h2>Тест откроется после анкеты</h2><p>Нужно выбрать отрасль, специализацию, предполагаемый уровень, профессиональные роли и мягкие навыки. Ответы сохраняются в истории.</p>${button('Заполнить анкету','nav','data-page="survey"')}</section>`;if(test&&!result){const q=test.questions[testIndex];return `${title('Подтверждение навыков',test.spec+' · '+test.grade,button('Выйти из теста','exit-test','',true))}<div class="test-workspace"><div class="test-progress"><span>Вопрос ${testIndex+1} из ${test.questions.length}</span><span id="test-countdown" class="test-countdown" role="timer" aria-label="Оставшееся время" aria-live="off">${icon('clock','small-icon')}<strong>20:00</strong></span></div><div class="question-progress" role="progressbar" aria-label="Прогресс теста" aria-valuemin="0" aria-valuemax="${test.questions.length}" aria-valuenow="${testIndex+1}"><span class="question-progress-fill" style="transform:scaleX(${(testIndex+1)/test.questions.length})"></span></div><form id="answer-form" class="panel test-question"><div class="eyebrow">${esc(q.topic)}</div><h2>${esc(q.prompt)}</h2><div class="answer-list">${q.options.map((label,i)=>`<label class="answer-option"><input type="radio" name="answer" value="${i}" ${answers[testIndex]===i?'checked':''} required><span>${esc(label)}</span></label>`).join('')}</div><p data-error class="form-error" role="alert"></p><div class="question-actions">${testIndex>0?button('Назад','previous-question','type="button"',true):'<span></span>'}<button class="button" type="submit">${testIndex===test.questions.length-1?'Завершить тест':'Следующий вопрос'} ${icon('arrow','small-icon')}</button></div></form></div>`;}if(result)return `${title('Результат тестирования',test.spec+' · '+test.grade)}<div class="result-layout"><section class="panel test-result"><div class="result-number">${result.score}<span>/100</span></div><h2>${result.passed?'Уровень подтверждён':'Пока ниже порога'}</h2><p>${result.applied?'Категория присвоена автоматически. Профиль может участвовать в поиске.':result.locked?'Результат сохранён. Смена категории ограничена интервалом 90 дней.':'Категория не понижается. Обновите анкету, если хотите проверить другой уровень.'}</p>${button('Вернуться в кабинет','finish-test')}${button('Пройти другой тест','retry-test','',true)}</section><section class="panel resume-section"><h2>Обратная связь</h2>${result.feedback.map(f=>`<div class="feedback-row">${icon(f.correct?'checkCircle':'close','small-icon')}<div><strong>${esc(f.topic)}</strong><p>${esc(f.explanation)}</p></div></div>`).join('')}<p class="subtext">Это результат MVP-оценивания. Психометрическая валидация банка ещё не проведена.</p></section></div>`;return `${title('Подтверждение навыков','Тест соответствует последней сохранённой анкете.')}<div class="test-landing"><section class="panel test-start"><div class="eyebrow">Новая попытка</div><h2>${esc(p.spec)} · ${esc(p.grade)}</h2><p>6 вопросов, до 20 минут. Порог подтверждения — 67 баллов. Для другой категории сначала обновите анкету.</p><form id="start-test-form"><input type="hidden" name="spec" value="${esc(p.spec)}"><input type="hidden" name="grade" value="${esc(p.grade)}"><div class="inline-note">${icon('shield')}Каждая попытка получает свой порядок ответов и параметры задач. Результат не понижает текущий подтверждённый уровень.</div><p class="form-error" data-error role="alert"></p><button class="button" type="submit">Начать тест ${icon('arrow','small-icon')}</button></form></section><aside class="panel resume-section"><h3>Данные анкеты</h3><p>${esc(state.surveys[0].industry)} · ${esc(state.surveys[0].workStyle)}</p>${tag(state.surveys[0].roles)}${button('Обновить анкету','nav','data-page="survey"',true)}</aside></div><section class="panel history-panel"><h2>История попыток</h2>${state.tests.filter(t=>t.result).length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Дата</th><th>Категория</th><th>Баллы</th><th>Результат</th></tr></thead><tbody>${state.tests.filter(t=>t.result).map(t=>`<tr><td>${date(t.created)}</td><td>${esc(t.spec)} / ${esc(t.grade)}</td><td>${t.result.score}/100</td><td>${badge(t.result.passed?'Пройден':'Не подтверждён',t.result.passed?'green':'')}</td></tr>`).join('')}</tbody></table></div>`:empty('Это будет ваша первая попытка','Здесь сохраняются результаты всех завершённых тестов.')}</section>`;}
function invitationsPage(){const employer=role==='employer';return `${title(employer?'Отправленные приглашения':'Приглашения от компаний',employer?'Условия предложений, решения кандидатов и доступные контакты.':'Посмотрите задачи и зарплату. Решение открыть контакт принимаете вы.',employer?button('Найти кандидата','nav','data-page="catalog"'):'' )}${state.invites.length?`<div class="inbox-list">${state.invites.map(i=>`<article class="panel inbox-card"><div class="inbox-top"><span class="company-symbol">${esc((employer?i.candidateName:i.company).slice(0,1))}</span><div><strong>${esc(employer?i.candidateName:i.company)}</strong><small>${date(i.created)}${i.synthetic?' · Демопрофиль':''}</small></div>${status(i.status)}</div><h2>${esc(i.title)}</h2><strong class="offer-salary">${salary(i.min,i.max)}</strong><p>${esc(i.description.slice(0,240))}</p><div class="inbox-actions">${button('Посмотреть предложение','offer-detail','data-id="'+i.id+'"',true)}${i.status==='accepted'?button('Открыть диалог','chat','data-id="'+i.id+'"'):''}${employer?`<span>${i.email?esc(i.email):'Контакты скрыты до согласия'}</span>`:''}</div></article>`).join('')}</div>`:empty(employer?'Приглашений пока нет':'Новых предложений пока нет',employer?'Найдите подходящего человека и предложите условия. Вакансия для этого не обязательна.':'Подтвердите навыки и включите видимость резюме. Можно также откликаться на вакансии.',button(employer?'Подобрать кандидатов':'Смотреть вакансии','nav',`data-page="${employer?'catalog':'jobs'}"`))}`;}
function applicationsPage(){const employer=role==='employer';return `${title(employer?'Отклики на вакансии':'Мои отклики',employer?'Просматривайте кандидатов и обновляйте статус с обратной связью.':'Ответы компаний и следующий шаг по каждому отклику.')}<div class="inbox-list">${state.applications.length?state.applications.map(a=>`<article class="panel inbox-card"><div class="inbox-top"><div><strong>${esc(employer?a.candidateName:a.job?.company||'Компания')}</strong><small>${date(a.created)}${a.synthetic?' · Демовакансия':''}</small></div>${status(a.status)}</div><h2>${esc(a.job?.title||'Вакансия в архиве')}</h2>${a.letter?`<p class="multiline">${esc(a.letter)}</p>`:''}${a.feedback?`<div class="inline-note">${icon('mail')}<span>${esc(a.feedback)}</span></div>`:''}<div class="inbox-actions">${employer?`${button('Ответить кандидату','review-application','data-id="'+a.id+'"')}${button('Посмотреть резюме','candidate-detail','data-id="'+a.owner+'" data-application-id="'+a.id+'"',true)}${a.email?`<a href="mailto:${esc(a.email)}">${esc(a.email)}</a>`:''}`:button('Посмотреть вакансию','job-detail','data-id="'+a.jobId+'"',true)}${!a.synthetic?button('Диалог','chat','data-id="'+a.id+'"',true):''}</div></article>`).join(''):empty('Откликов пока нет',employer?'Опубликуйте вакансию, чтобы кандидаты могли проявить инициативу.':'Найдите предложение и отправьте резюме с сопроводительным письмом.',button(employer?'Создать вакансию':'Найти вакансию',employer?'new-job':'nav',employer?'':'data-page="jobs"'))}</div>`;}
const needContextLine=c=>{const parts=[c?.format,c?.format!=='Удалённо'?c?.city:'',c?.budgetMin||c?.budgetMax?budgetLabel(c):'',c?.team?'описание команды':''].filter(Boolean);return parts.length?`<p class="saved-context">${icon('users','small-icon')}${esc(parts.join(' · '))}</p>`:'';};
function needsPage(){return `${title('Сохранённые подборки','Возвращайтесь к запросу и уточняйте фильтры.',button('Новая подборка','nav','data-page="catalog"'))}${state.needs.length?`<div class="saved-grid">${state.needs.map(n=>`<article class="panel saved-card"><div class="eyebrow">${date(n.created)}</div><h2>${esc(n.title)}</h2>${tag([n.spec,n.grade,...n.stack])}${needContextLine(n.context)}${n.snapshot?`<p class="saved-snapshot">При сохранении: ${plural(n.snapshot.total,'кандидат','кандидата','кандидатов')} в категории ${esc(n.spec)} · ${esc(n.grade)}</p>`:''}<div class="modal-actions">${button('Открыть подборку','open-need','data-id="'+n.id+'"')}${button('Удалить','delete-need','data-id="'+n.id+'"',true)}</div></article>`).join('')}</div>`:empty('Сохраните первый запрос','В поиске кандидатов опишите потребность и нажмите «Сохранить поиск».')}`;}
function settingsPage(){const p=state.privacy;return `${title('Настройки','Управляйте видимостью и обработкой данных.')}<div class="settings-layout"><section class="panel"><form id="settings-form"><h2>Приватность</h2>${[['visible','Показывать резюме работодателям','В поиск попадает только профиль с подтверждённой категорией.'],['consent','Согласие на обработку и публикацию профиля','Отзыв согласия сразу скрывает резюме из поиска и запрещает новые приглашения.'],['fspVisible','Показывать достижения ФСП работодателям','Можно скрыть спортивную историю, оставив резюме в поиске.'],['notifications','Уведомления в кабинете','Показывать новые предложения и обновления в личном кабинете. Email-рассылки не подключены.']].map(([key,h,t])=>`<label class="setting-row"><div><strong>${h}</strong><p>${t}</p></div><input type="checkbox" name="${key}" ${(key==='fspVisible'?p[key]!==false:p[key])?'checked':''}></label>`).join('')}<p class="form-error" data-error role="alert"></p><button class="button" type="submit">Сохранить настройки</button></form></section><aside class="panel resume-section"><h3>Аккаунт</h3><p>${esc(state.user.email)}</p><p>Вход через ChatGPT. Пароли сервис не хранит.</p><a href="/signout-with-chatgpt?return_to=/" target="_top">Выйти из аккаунта</a><h3>ФСП ID</h3><p>${state.profile.fsp?esc(state.profile.fsp.id)+' · тестовая привязка':'Пока не привязан'}</p><p>Можно проверить привязку и импорт истории на тестовых данных. Подключение реального реестра отложено.</p>${button('Управлять ФСП ID','fsp-manage','',true)}<a href="#privacy">Подробнее о данных</a></aside></div>`;}
function companyPage(){const c=state.company;return `${title('Профиль компании','Эта информация сопровождает ваши вакансии и приглашения.')}<section class="panel company-form"><form id="company-form"><div class="form-row">${field('Название','name',c.name,'text','required')}${field('Город','city',c.city)}</div><div class="form-row">${field('Направление деятельности','industry',c.industry)}${select('Размер команды','size',['1–50','51–200','201–1000','1000+'],c.size)}</div>${textarea('О компании и команде','description',c.description,'required minlength="20" maxlength="4000"')}<div class="form-row">${field('Email для кандидатов','contact',c.contact,'email','required')}${field('Сайт','website',c.website,'url')}</div><p class="form-error" data-error role="alert"></p><button class="button" type="submit">Сохранить компанию</button></form></section>`;}
function tasksPage(){const employer=role==='employer',rows=state.tasks.filter(t=>employer?t.owner===state.user.id:t.status==='published');return `${title('Короткие задания',employer?'Практические задачи для свежего сигнала о навыках.':'Опишите подход к задаче компании. Решение оценивает работодатель.',employer?button('Создать задание','new-task'):'' )}<div class="saved-grid">${rows.length?rows.map(t=>{const ownAnswer=state.submissions.find(s=>s.taskId===t.id&&s.owner===state.user.id);return `<article class="panel saved-card"><div class="eyebrow">${esc(t.company)} · ${esc(t.spec)} · ~15 минут</div><h2>${esc(t.title)}</h2><p class="multiline">${esc(t.description)}</p>${ownAnswer?status(ownAnswer.status):''}${ownAnswer?.feedback?`<p>${esc(ownAnswer.feedback)}</p>`:''}${!employer&&!ownAnswer?button('Предложить решение','answer-task','data-id="'+t.id+'"'):''}</article>`;}).join(''):empty('Заданий пока нет',employer?'Добавьте задачу из реальной работы команды.':'Здесь появятся задачи, опубликованные компаниями.')}</div>${employer&&state.submissions.length?`<section class="panel history-panel"><h2>Решения кандидатов</h2>${state.submissions.map(s=>`<div class="submission"><strong>${esc(s.candidateName)} · ${esc(s.title)}</strong>${status(s.status)}<p class="multiline">${esc(s.answer)}</p>${s.feedback?`<p>Обратная связь: ${esc(s.feedback)}</p>`:button('Оставить обратную связь','review-task','data-id="'+s.id+'"')}</div>`).join('')}</section>`:''}`;}
function methodPage(){return `${title('Как устроена ФСП Карьера','Обратный подбор: инициативу проявляет работодатель, решение принимает кандидат.')}<div class="documentation"><section><h2>Подтверждённая категория</h2><p>Кандидат выбирает специализацию и предполагаемый уровень. После успешного теста сервер присваивает категорию «специализация + грейд». Непройденный тест не понижает прежний уровень. Смена категории ограничена интервалом 90 дней.</p><h2>Механика тестирования</h2><p>Для каждого направления есть банк шаблонов и фиксированный план теста по уровню. Попытки меняют параметры расчётных задач и порядок ответов. Правильные ответы остаются на сервере. Шесть вопросов, 20 минут, порог 67 баллов.</p><div class="inline-note">${icon('document')}Банк версии 1 небольшой. Перестановка ответов и параметры затрудняют перенос готовых ответов, но не решают утечку шаблонов. Сопоставимость сложности пока задана рубрикой; экспертная и психометрическая валидация не проведена.</div><h2>Объяснимый подбор</h2><p>В поиске участвуют только подтверждённые и опубликованные профили. Потребность разбирается по правилам на ключевых словах: специализация, грейд, технологии, формат и бюджет. Это детерминированный разбор, а не нейросетевая модель; работодатель видит его результат и слова, на которые он опирается.</p><p>Сначала выбирается категория. Рядом с точной категорией сервис рекомендует до трёх соседних: грейд выше или ниже и смежное направление с общими технологиями. Внутри категории кандидаты упорядочены по баллу соответствия; при равенстве выше сильнее подтверждённый профиль — тест и ФСП.</p><table class="data-table"><thead><tr><th>Признак</th><th>Источник</th><th>Вклад</th></tr></thead><tbody><tr><td>Специализация</td><td>Тест</td><td>25; смежное направление — 8</td></tr><tr><td>Грейд</td><td>Тест</td><td>15; соседний грейд — 6</td></tr><tr><td>Технологии</td><td>Резюме</td><td>до 20 — доля совпавших с запросом</td></tr><tr><td>Результат теста</td><td>Тест</td><td>до 20 — (балл − 50) × 0,4</td></tr><tr><td>Достижения ФСП</td><td>ФСП · тестовые данные</td><td>до 10 — уровень лучшего результата, профильность дисциплины и давность</td></tr><tr><td>Формат и город</td><td>Резюме и контекст</td><td>до 4</td></tr><tr><td>Зарплатные ожидания</td><td>Резюме и контекст</td><td>до 4; ноль при превышении бюджета на 30%</td></tr><tr><td>Предметная область</td><td>Резюме и контекст</td><td>до 2 — общие темы описания команды и резюме</td></tr></tbody></table><p>Один верный ответ теста — около 7 баллов. Участие или финал ФСП поднимают кандидата при близких результатах теста, но не перекрывают разницу в целый вопрос; победа весит примерно полтора вопроса. Без истории ФСП кандидат остаётся в выдаче и может набрать 90 баллов; история, скрытая кандидатом, не учитывается.</p><p>Контекст команды необязателен. Незаданный признак получает полный балл у всех и не меняет порядок. Технологии заявляет кандидат; подтверждаются категория и результат теста. Веса — гипотеза MVP: их нужно откалибровать на размеченных парах «потребность — кандидат».</p><h2>Согласие на контакт</h2><p>Работодатель отправляет приглашение с описанием задачи и обязательной зарплатой от–до. Кандидат видит условия и принимает или отклоняет предложение. Сервер открывает его контакт только конкретной компании после принятия либо самостоятельного отклика.</p><h2>Без истории ФСП</h2><p>Все основные функции работают без ФСП ID и достижений. Реестр не подключён: в демонстрации достижения синтетические и везде помечены как тестовые данные.</p></section><aside class="panel"><h3>С чего начать</h3>${button('Создать резюме','join','data-role="candidate"')}${button('Создать кабинет компании','join','data-role="employer"',true)}<p>Для проверки можно создать оба кабинета на одном аккаунте. Доступ к данным каждого сценария проверяется сервером.</p><a href="/openapi.json" target="_blank">Спецификация API</a></aside></div>`;}
function privacyPage(){return `${title('Данные и приватность','Правила доступа в MVP.')}<article class="panel legal-document"><h2>Что сохраняется</h2><p>Идентификатор и email аккаунта ChatGPT, заполненное резюме, профиль компании, результаты тестов, вакансии, приглашения, отклики, решения заданий и сообщения. Данные хранятся в серверной базе Cloudflare D1 в инфраструктуре Sites.</p><h2>Кто видит профиль</h2><p>Кандидат имеет доступ только к собственному кабинету. Работодатели видят резюме после успешного теста, включённой видимости и согласия на публикацию. Email и телефон не передаются работодателю до принятия его приглашения или отклика на его вакансию.</p><h2>Как отозвать согласие</h2><p>Выключите согласие в настройках. Резюме исчезнет из выдачи, новые приглашения станут недоступны. Уже состоявшиеся взаимодействия и ранее открытые контакты останутся в истории сторон.</p><h2>Тестовые данные и ограничения</h2><p>Демонстрационные кандидаты и вакансии помечены в интерфейсе. Их приглашения и отклики сохраняются для проверки, но реальные люди их не получают. Привязка ФСП ID и история соревнований используют явно помеченные синтетические данные. Можно отдельно скрыть историю ФСП от работодателей. Реальный реестр и email-рассылки ещё не подключены.</p><p>Эта версия предназначена для проверки MVP. Размещение реальных персональных данных в эксплуатации потребует отдельной проверки инфраструктуры, локализации хранения и юридических условий.</p>${button('Открыть настройки','join','data-role="candidate"',true)}</article>`;}
function helpPage(){const groups=[['Резюме и поиск',[['Почему меня нет в поиске?','Профиль появляется в подборе после успешного тестирования. В настройках также должны быть включены видимость резюме и согласие на его публикацию.','Открыть настройки','settings','candidate'],['Кто видит мои контакты?','Компания получает контакт, когда вы принимаете её приглашение или сами откликаетесь на вакансию. До этого работодатель видит навыки, опыт и зарплатные ожидания.','Посмотреть приглашения','offers','candidate']]],['Подтверждение навыков',[['Что делать, если тест не пройден?','Сохранённая категория не понижается. Можно подготовиться и повторить попытку или проверить навыки на более низком уровне. Смена уже подтверждённой категории доступна раз в 90 дней.','Перейти к тестированию','tests','candidate'],['Обязательно ли участвовать в ФСП?','Нет. Подтверждение навыков, поиск работы и приглашения доступны без истории соревнований. ФСП ID и достижения доступны в демонстрационном режиме. Реальный реестр подключим на следующем этапе; участие в соревнованиях не влияет на доступ к сервису.']]],['Аккаунт и предложения',[['Можно ли использовать оба кабинета?','Да. В меню аккаунта можно создать профиль кандидата и профиль компании, а затем переключаться между ними. У каждого кабинета свои резюме, подборки и предложения.'],['Почему демонстрационный кандидат не отвечает?','Демонстрационные профили показывают, как устроен подбор. За ними нет реального пользователя, поэтому приглашение сохранится, но ответа не будет. Такие профили отмечены в выдаче.']]]];return `${title('Помощь','Ответы о профиле, навыках и предложениях от компаний.')}<div class="help-layout"><div class="faq-list">${groups.map(([heading,questions])=>`<section class="faq-group"><h2>${heading}</h2>${questions.map(([question,answer,label,target,wanted])=>`<details class="faq-item"><summary><span>${question}</span><span class="faq-toggle" aria-hidden="true"></span></summary><div class="faq-answer"><div class="faq-answer-copy"><p>${answer}</p>${label?`<a href="#${target}" data-action="join" data-role="${wanted}">${label} ${icon('arrow','small-icon')}</a>`:''}</div></div></details>`).join('')}</section>`).join('')}</div><aside class="help-shortcuts"><h2>Быстрый переход</h2><a href="#profile" data-action="join" data-role="candidate">${icon('user','small-icon')}Моё резюме ${icon('arrow','small-icon')}</a><a href="#tests" data-action="join" data-role="candidate">${icon('shield','small-icon')}Подтвердить навыки ${icon('arrow','small-icon')}</a><a href="#jobs">${icon('briefcase','small-icon')}Вакансии ${icon('arrow','small-icon')}</a><a href="#privacy">${icon('lock','small-icon')}Данные и приватность ${icon('arrow','small-icon')}</a></aside></div>`;}
function toggleFAQ(details){const content=details.querySelector('.faq-answer'),summary=details.querySelector('summary');const opening=details.dataset.motionState==='closing'||!details.open;const initial=details.open?content.getBoundingClientRect().height:0;content.getAnimations().forEach(a=>a.cancel());details.dataset.motionState=opening?'opening':'closing';summary.setAttribute('aria-expanded',String(opening));if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){details.open=opening;delete details.dataset.motionState;return;}details.open=true;const target=content.scrollHeight;const animation=content.animate([{height:`${initial}px`,opacity:opening?0:1},{height:`${opening?target:0}px`,opacity:opening?1:0}],{duration:opening?240:180,easing:'cubic-bezier(.22,1,.36,1)'});animation.finished.then(()=>{if(details.dataset.motionState===(opening?'opening':'closing')){details.open=opening;delete details.dataset.motionState;}}).catch(()=>{});}

function renderView(){const wrongRole=(role==='candidate'&&['catalog','company','needs','invites'].includes(page))||(role==='employer'&&['profile','survey','tests','settings','offers'].includes(page));if(wrongRole)page=state.roles.includes(role)?'dashboard':'home';const publicPages=['home','employers','jobs','method','privacy','help'];if(!publicPages.includes(page)&&!state.roles.includes(role)){page='home';}const view={home,employers:employerHome,dashboard,profile:profilePage,survey:surveyPage,tests:testsPage,catalog:catalogPage,jobs:jobsPage,offers:invitationsPage,invites:invitationsPage,applications:applicationsPage,needs:needsPage,settings:settingsPage,company:companyPage,tasks:tasksPage,method:methodPage,privacy:privacyPage,help:helpPage}[page]||home;app.innerHTML=header()+`<div class="site-container">${nav()}<main class="${publicPages.includes(page)?'public-main':'cabinet-main'}">${view()}</main>${footer()}</div>`;document.title=(page==='home'?'Работа в IT':({catalog:'Поиск кандидатов',jobs:'Вакансии',dashboard:'Личный кабинет',profile:'Моё резюме',survey:'Анкета кандидата',tests:'Подтверждение навыков'}[page]||'Личный кабинет'))+' — ФСП Карьера';}
let renderedPage=null,renderedAttempt=null,renderedQuestion=0,renderedProgress=0;
function testClock(){
 const clock=document.getElementById('test-countdown');
 if(!clock||!test||result)return;
 const seconds=Math.max(0,Math.ceil((test.expires-Date.now())/1000));
 clock.querySelector('strong').textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;
 clock.classList.toggle('time-low',seconds<=120&&seconds>0);
 clock.classList.toggle('time-expired',seconds===0);
 if(seconds===0){
  const form=document.getElementById('answer-form');
  form?.querySelectorAll('input,button[type="submit"]').forEach(el=>el.disabled=true);
  const error=form?.querySelector('[data-error]');
  if(error)error.textContent='Время истекло. Завершите попытку и начните новую; текущая категория сохранится.';
 }
}
function render(){
 const beforePage=renderedPage,beforeAttempt=renderedAttempt,beforeQuestion=renderedQuestion,beforeProgress=renderedProgress;
 renderView(); testClock(); prepareResumePDF();
 const activeQuestion=page==='tests'&&test&&!result;
 const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
 if(!reduced){
  const motion={duration:300,easing:'cubic-bezier(.22,1,.36,1)'};
  if(beforePage!==null&&beforePage!==page){
   const order=['home','employers','dashboard','profile','survey','tests','catalog','needs','offers','invites','jobs','applications','tasks','company','settings','method','privacy','help'];
   const direction=order.indexOf(page)>=order.indexOf(beforePage)?1:-1;
   app.querySelector('main')?.animate([{opacity:0,transform:`translateX(${direction*32}px)`},{opacity:1,transform:'translateX(0)'}],motion);
  }else if(activeQuestion&&(beforeAttempt!==test.id||beforeQuestion!==testIndex)){
   const direction=beforeAttempt===test.id&&testIndex<beforeQuestion?-1:1;
   app.querySelector('.test-question')?.animate([{opacity:0,transform:`translateX(${direction*48}px)`},{opacity:1,transform:'translateX(0)'}],{...motion,duration:340});
  }
  const fill=app.querySelector('.question-progress-fill');
  if(fill){const progress=(testIndex+1)/test.questions.length;fill.animate([{transform:`scaleX(${beforeAttempt===test.id?beforeProgress:0})`},{transform:`scaleX(${progress})`}],{...motion,duration:380});}
 }
 renderedPage=page;renderedAttempt=activeQuestion?test.id:null;renderedQuestion=testIndex;renderedProgress=activeQuestion?(testIndex+1)/test.questions.length:0;
}
setInterval(testClock,1000);

function historyProfileSection(kind,profile=state.profile){const rows=resumeHistory(profile,kind);return `<h2>${kind==='workEntries'?'Опыт работы':'Образование и курсы'}</h2>${rows.length?rows.map(row=>`<div class="resume-history-preview">${historyHeading(row,kind)?`<h3>${esc(historyHeading(row,kind))}</h3>`:''}<p class="subtext">${[row.level,historyPeriod(row)].filter(Boolean).map(esc).join(' · ')}</p>${row.description?`<p class="multiline">${esc(row.description)}</p>`:''}</div>`).join(''):'<p class="subtext">Раздел пока не заполнен. В PDF он не появится.</p>'}`;}
let resumeDraft=null;
function readResumeDraft(){
 const form=document.getElementById('profile-form');if(!form)return resumeDraft;
 const values=new FormData(form),get=name=>String(values.get(name)||'');
 resumeDraft={headline:get('headline'),languages:get('languages'),achievements:get('achievements'),
  skillGroups:resumeDraft.skillGroups.map((_,i)=>({label:get('skill-label-'+i),text:get('skill-text-'+i),description:get('skill-description-'+i)})),
  projects:resumeDraft.projects.map((_,i)=>({name:get('project-name-'+i),description:get('project-description-'+i),url:get('project-url-'+i)})),
  links:resumeDraft.links.map((_,i)=>({label:get('link-label-'+i),url:get('link-url-'+i)})),
  ...Object.fromEntries(['workEntries','educationEntries'].map(kind=>[kind,(resumeDraft[kind]||[]).map((_,i)=>Object.fromEntries(Object.keys(historyDefaults[kind]).map(key=>[key,key==='current'?values.get(kind+'-'+key+'-'+i)==='on':get(kind+'-'+key+'-'+i)])))]))};
 return resumeDraft;
}
function historyEditor(kind){
 const work=kind==='workEntries',rows=resumeDraft[kind]||[],name=(key,i)=>kind+'-'+key+'-'+i;
 return `<section class="resume-builder-section resume-history-editor" id="resume-${work?'work':'education'}"><div class="resume-history-heading"><h3>${work?'Опыт работы':'Образование и курсы'}</h3><span>${rows.length} / 10</span></div><p>${work?'Добавьте место работы, свою роль и результаты.':'Добавьте учебное заведение или курс и программу обучения.'} Раздел необязательный.</p>${rows.map((g,i)=>`<article class="resume-builder-item"><div class="resume-builder-item-head"><strong>${work?'Место работы':'Образование'} ${i+1}</strong><button type="button" class="resume-builder-remove" data-action="resume-remove" data-kind="${kind}" data-index="${i}" aria-label="Удалить ${work?'место работы':'образование'} ${i+1}">Удалить</button></div><div class="form-row">${field(work?'Компания':'Учебное заведение / платформа',name(work?'company':'institution',i),g[work?'company':'institution'],'text',`maxlength="160" placeholder="${work?'Название компании':'Университет или платформа курса'}"`)}${field(work?'Должность':'Специальность / название курса',name(work?'position':'program',i),g[work?'position':'program'],'text',`maxlength="160" placeholder="${work?'ML Engineer':'Прикладная математика и информатика'}"`)}</div>${work?'':select('Уровень образования',name('level',i),['','Среднее','Среднее профессиональное','Бакалавриат','Специалитет','Магистратура','Аспирантура','Курс / сертификат'],g.level)}<div class="form-row resume-history-dates">${field('Начало',name('start',i),g.start,'text','maxlength="40" placeholder="Март 2023"')}${field(work?'Окончание':'Окончание / ожидаемый выпуск',name('end',i),g.end,'text',`maxlength="40" placeholder="${work&&g.current?'Настоящее время':'Июнь 2025'}" ${work&&g.current?'readonly aria-disabled="true"':''}`)}</div>${work?`<label class="check-row resume-history-current"><input type="checkbox" name="${name('current',i)}" data-history-current="${i}" ${g.current?'checked':''}>Работаю здесь сейчас</label>`:''}${textarea(work?'Задачи и результаты':'Описание (необязательно)',name('description',i),g.description,`maxlength="${work?3000:1000}" placeholder="${work?'Что делали и какого результата добились. Каждый пункт — с новой строки.':'Квалификация, дипломный проект или содержание курса.'}"`)}</article>`).join('')}${!rows.length?`<div class="resume-history-empty">${work?'Нет опыта? Можно добавить стажировку или оставить раздел пустым.':'Добавьте образование, если хотите показать его в резюме.'}</div>`:''}${rows.length<10?`<button type="button" class="button secondary resume-builder-add" data-action="resume-add" data-kind="${kind}">${icon('plus','small-icon')} ${work?'Добавить место работы':'Добавить образование или курс'}</button>`:''}</section>`;
}
function resumeEditorFields(){const r=resumeDraft;return `<div class="stack">${historyEditor('workEntries')}${historyEditor('educationEntries')}
 <section class="resume-builder-section" id="resume-skills"><h3>Группы навыков</h3><p>Например: ML & AI, NLP & LLM, Tools. Навыки попадут в PDF и будут использоваться для поиска; описание необязательно.</p>${r.skillGroups.map((g,i)=>`<div class="resume-builder-item"><div class="resume-builder-item-head"><strong>Группа ${i+1}</strong><button type="button" class="resume-builder-remove" data-action="resume-remove" data-kind="skillGroups" data-index="${i}">Удалить группу</button></div>${field('Название группы','skill-label-'+i,g.label,'text','maxlength="60" placeholder="ML & AI"')}${field('Навыки через запятую','skill-text-'+i,g.text,'text','maxlength="300" placeholder="Python, PyTorch, Computer Vision, RecSys"')}${textarea('Описание группы (необязательно)','skill-description-'+i,g.description||'','maxlength="500" placeholder="Какие задачи решаете с этими навыками"')}</div>`).join('')}${r.skillGroups.length<6?`<button type="button" class="button secondary resume-builder-add" data-action="resume-add" data-kind="skillGroups">+ Добавить группу навыков</button>`:''}</section>
 <section class="resume-builder-section" id="resume-projects"><h3>Проекты</h3><p>Название, ваша работа и результат. Ссылку можно оставить пустой.</p>${r.projects.map((g,i)=>`<div class="resume-builder-item"><div class="resume-builder-item-head"><strong>Проект ${i+1}</strong><button type="button" class="resume-builder-remove" data-action="resume-remove" data-kind="projects" data-index="${i}">Удалить проект</button></div>${field('Название проекта','project-name-'+i,g.name,'text','maxlength="100"')}${textarea('Описание: что сделали и какой результат','project-description-'+i,g.description,'maxlength="1200"')}${field('Ссылка на проект','project-url-'+i,g.url,'url','maxlength="300" placeholder="https://github.com/…"')}</div>`).join('')}${r.projects.length<6?`<button type="button" class="button secondary resume-builder-add" data-action="resume-add" data-kind="projects">+ Добавить проект</button>`:''}</section>
 <section class="resume-builder-section"><h3>Достижения и языки</h3>${textarea('Достижения — каждое с новой строки','achievements',r.achievements,'maxlength="1800" placeholder="Название соревнования — результат (год)"')}${textarea('Языки и уровень','languages',r.languages,'maxlength="500" placeholder="Русский — родной; английский — B2"')}<p class="resume-builder-saved">Это ваши достижения. История ФСП добавляется отдельно и сохраняет отметку об источнике.</p></section>
 <section class="resume-builder-section"><h3>Ссылки в шапке</h3><p>Telegram, GitHub, портфолио или личный сайт. Ссылки попадут в ваш PDF.</p>${r.links.map((g,i)=>`<div class="resume-builder-item"><div class="resume-builder-item-head"><strong>Ссылка ${i+1}</strong><button type="button" class="resume-builder-remove" data-action="resume-remove" data-kind="links" data-index="${i}">Удалить ссылку</button></div><div class="form-row">${field('Название','link-label-'+i,g.label,'text','maxlength="40" placeholder="GitHub"')}${field('Адрес','link-url-'+i,g.url,'url','maxlength="300" placeholder="https://…"')}</div></div>`).join('')}${r.links.length<4?`<button type="button" class="button secondary resume-builder-add" data-action="resume-add" data-kind="links">+ Добавить ссылку</button>`:''}</section></div>`;}
function editResumeDetails(){editProfile('skills');}
function updateResumeEditor(kind,removeIndex=null){
 if(!['skillGroups','projects','links','workEntries','educationEntries'].includes(kind))return;readResumeDraft();
 if(removeIndex!==null)resumeDraft[kind].splice(removeIndex,1);
 else{const max=kind==='links'?4:['workEntries','educationEntries'].includes(kind)?10:6;if(resumeDraft[kind].length>=max)return;resumeDraft[kind].push(historyDefaults[kind]?{...historyDefaults[kind]}:kind==='skillGroups'?{label:'',text:''}:kind==='projects'?{name:'',description:'',url:''}:{label:'',url:''});}
 const panel=overlay.querySelector('.modal'),scroll=panel.scrollTop;document.getElementById('resume-blocks-editor').innerHTML=resumeEditorFields();panel.scrollTop=scroll;
}
function resumeExtraSections(){const r=state.profile.resume||{};return (r.skillGroups?.length||r.languages?`<article class="panel resume-section"><div class="section-heading"><h2>Группы навыков</h2></div><dl class="resume-builder-preview">${(r.skillGroups||[]).map(g=>`<dt>${esc(g.label)}</dt><dd class="multiline">${esc(g.text)}${g.description?`<p class="subtext">${esc(g.description)}</p>`:''}</dd>`).join('')}${r.languages?`<dt>Языки</dt><dd class="multiline">${esc(r.languages)}</dd>`:''}</dl></article>`:'')+(r.achievements?`<article class="panel resume-section"><h2>Достижения</h2><p class="multiline">${esc(r.achievements)}</p></article>`:'')+(r.projects?.length?`<article class="panel resume-section"><div class="section-heading"><h2>Проекты</h2></div>${r.projects.map(g=>`<div class="resume-profile-project"><h3>${esc(g.name)}</h3><p class="multiline">${esc(g.description)}</p>${g.url?`<a href="${esc(g.url)}" target="_blank" rel="noopener noreferrer">${esc(g.url)}</a>`:''}</div>`).join('')}</article>`:'');}
function scrollResumeSection(section){overlay.querySelector('#resume-'+section)?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}
function editProfile(section=''){
 const p=state.profile;
 resumeDraft=structuredClone({headline:'',languages:'',achievements:'',links:[],skillGroups:[],projects:[],...p.resume,workEntries:resumeHistory(p,'workEntries'),educationEntries:resumeHistory(p,'educationEntries')});
 if(!resumeDraft.skillGroups.length)resumeDraft.skillGroups.push(p.stack.length?{label:'Технологии',text:p.stack.join(', '),description:''}:{label:'',text:'',description:''});
 modal('Редактировать резюме','Заполняйте только нужные поля. Группы навыков, проекты и другие блоки попадут в PDF.',`<form id="profile-form">
 <nav class="resume-editor-nav" aria-label="Разделы резюме">${[['basics','Основное'],['work','Опыт'],['education','Образование'],['skills','Навыки'],['projects','Проекты']].map(([id,label])=>`<button type="button" data-action="resume-section" data-section="${id}">${label}</button>`).join('')}</nav>
 <div class="stack" id="resume-basics"><div class="form-row">${field('Имя и фамилия','name',p.name,'text','maxlength="100"')}${field('Город','city',p.city,'text','maxlength="80"')}</div>${field('Заголовок резюме','headline',resumeDraft.headline,'text','maxlength="100" placeholder="Например, ML Researcher / Backend Developer"')}<div class="form-row">${field('Опыт работы','experience',p.experience)}${select('Формат работы','format',['Удалённо','Гибрид','Офис'],p.format)}</div>
 <div class="form-row">${field('Зарплата от, ₽','min',p.min??'','number','placeholder="Не указана"')}${field('Зарплата до, ₽','max',p.max??'','number','placeholder="Не указана"')}</div>${field('Телефон (необязательно)','phone',p.phone||'','tel')}<p class="subtext">Email аккаунта: ${esc(state.user.email)}. Контакты скрыты до согласия на знакомство.</p>
 ${textarea('О себе','about',p.about,'maxlength="5000"')}</div>
 <div id="resume-blocks-editor">${resumeEditorFields()}</div>${formEnd('Сохранить резюме')}</form>`,true);
 if(section)scrollResumeSection(section);
}
function candidateDetail(id,applicationId){const application=applicationId?state.applications.find(a=>a.id===applicationId):null,inBank=application?null:state.candidates.find(c=>c.id===id),c=application?.candidate||inBank;if(!c)return;const m=c.match;const heading=m.score===null?`Сила подтверждённого профиля: ${m.strength}/30`:inBank?`${m.score}/100 — соответствие потребности`:`${m.score}/100 — соответствие вакансии «${esc(application.job?.title||'')}»`;modal(esc(c.name),esc(c.city)+' · '+esc(c.experience),`<h2 class="detail-position">${esc(titles[c.spec])}</h2><strong class="offer-salary">${salary(c.min,c.max)}</strong>${tag([c.grade,...c.stack])}<section class="detail-section"><h3>О себе</h3><p class="multiline">${esc(c.about)}</p></section>${historyProfileSection('workEntries',c)}${historyProfileSection('educationEntries',c)}${c.roles?.length?tag(c.roles):''}${c.softSkills?.length?tag(c.softSkills):''}${fspSection(c.fsp)}${matchBreakdown(m,heading,m.score===null?30:100)}<p class="subtext">${c.verified?`Категория подтверждена ${date(c.verifiedAt)}.`:'Категория не подтверждена тестом.'} ${c.synthetic?'Демонстрационный профиль.':''}</p><div class="inline-note">${icon(c.email?'checkCircle':'lock')}<span>${c.email?esc(c.email)+(c.phone?' · '+esc(c.phone):''):'Контакт появится после принятия приглашения или отклика на вашу вакансию.'}</span></div><div class="modal-actions">${button('Сохранить','favorite','data-id="'+c.id+'"',true)}${button('Пригласить в команду','invite','data-id="'+c.id+'"')}</div>`,true);}
function comparison(){const rows=state.candidates.filter(c=>compare.includes(c.id));if(rows.length<2)return;const cell=fn=>rows.map(c=>`<td>${fn(c)}</td>`).join('');modal('Сравнение кандидатов',`${esc(state.need?.spec||'Текущая потребность')} · одинаковые критерии для ${rows.length} профилей`,`<div class="comparison-wrap"><table class="comparison-table"><thead><tr><th>Критерий</th>${rows.map(c=>`<th><strong>${esc(c.name)}</strong><span>${esc(c.spec)} · ${esc(c.grade)}</span></th>`).join('')}</tr></thead><tbody><tr><th>Соответствие</th>${cell(c=>`<strong class="comparison-score">${c.match.score===null?c.match.strength+'/30 — сила профиля':c.match.score+'/100'}</strong>`)}</tr><tr><th>Подтверждённый тест</th>${cell(c=>`${c.score}/100`)}</tr><tr><th>Совпавшие технологии</th>${cell(c=>esc(c.match.matched?.join(', ')||'Нет совпадений'))}</tr><tr><th>Опыт</th>${cell(c=>esc(c.experience))}</tr><tr><th>Формат</th>${cell(c=>esc(c.format||'Не указан'))}</tr><tr><th>Роли</th>${cell(c=>esc(c.roles?.join(', ')||'Не указаны'))}</tr><tr><th>Объяснение</th>${cell(c=>`<ul>${c.match.reasons.map(r=>`<li>${esc(r)}</li>`).join('')}</ul>`)}</tr></tbody></table></div><div class="modal-actions">${rows.map(c=>button(`Профиль: ${c.name.split(' ')[0]}`,'candidate-detail',`data-id="${c.id}"`,true)).join('')}</div>`,true);}
function invite(id){const c=state.candidates.find(c=>c.id===id);if(!c)return;modal('Приглашение в команду',esc(c.name)+' · '+esc(c.spec)+' / '+esc(c.grade),`<form id="invite-form" data-id="${id}"><div class="stack">${field('Предложение / роль','title',titles[c.spec]+' · '+state.company.name,'text','required maxlength="160"')}${textarea('Задачи команды и условия','description','','required minlength="20" maxlength="5000"')}<div class="form-row">${field('Зарплата от, ₽','min',c.min,'number','required min="1" max="10000000"')}${field('Зарплата до, ₽','max',c.max,'number','required min="1" max="10000000"')}</div>${field('Контакт компании','contact',state.company.contact,'email','required')}<div class="inline-note">${icon('lock')}Вакансия не обязательна. Контакт кандидата откроется только после принятия.${c.synthetic?' Демонстрационный кандидат не отвечает на предложения.':''}</div></div>${formEnd('Отправить приглашение')}</form>`);}
async function offerDetail(id){let i=state.invites.find(x=>x.id===id);if(!i)return;if(role==='candidate'&&i.status==='sent'){try{await api({action:'invite-status',id,status:'viewed'});await refresh();i=state.invites.find(x=>x.id===id);render();}catch(e){toast(e.message);}}modal(esc(i.title),esc(i.company)+' · '+date(i.created),`<strong class="offer-salary">${salary(i.min,i.max)}</strong>${status(i.status)}<p class="multiline detail-section">${esc(i.description)}</p><p>Контакт компании: <a href="mailto:${esc(i.contact)}">${esc(i.contact)}</a></p>${role==='candidate'&&['sent','viewed'].includes(i.status)?`<div class="inline-note">${icon('lock')}При принятии этой компании откроются email и телефон из вашего резюме.</div><div class="modal-actions">${button('Отклонить','respond',`data-id="${i.id}" data-status="declined"`,true)}${button('Принять приглашение','respond',`data-id="${i.id}" data-status="accepted"`)}</div>`:i.status==='accepted'?`<div class="modal-actions">${button('Открыть диалог','chat',`data-id="${i.id}"`)}</div>`:''}`,true);}
function jobDetail(id){const j=state.jobs.find(j=>j.id===id);if(!j){toast('Вакансия недоступна.');return;}modal(esc(j.title),esc(j.company)+(j.synthetic?' · Демовакансия':''),`<strong class="offer-salary">${salary(j.min,j.max)}</strong>${tag([j.grade,j.format,...j.stack])}<section class="detail-section"><h3>О работе</h3><p class="multiline">${esc(j.description)}</p><p>${esc(j.city||'Россия')}</p></section><div class="modal-actions">${j.own&&role==='employer'?button('Редактировать','edit-job',`data-id="${j.id}"`):button(state.applications.some(a=>a.jobId===j.id)?'Мои отклики':'Откликнуться',state.applications.some(a=>a.jobId===j.id)?'nav':'apply',state.applications.some(a=>a.jobId===j.id)?'data-page="applications"':`data-id="${j.id}"`)}</div>`,true);}
function jobForm(id){const j=state.jobs.find(j=>j.id===id)||{spec:'Backend',grade:'Middle',min:150000,max:220000,format:'Удалённо',stack:[]};modal(id?'Редактировать вакансию':'Новая вакансия','Зарплата и описание условий обязательны.',`<form id="job-form" data-id="${id||''}"><div class="stack">${field('Название должности','title',j.title||'','text','required maxlength="160"')}<div class="form-row">${select('Направление','spec',specs,j.spec)}${select('Грейд','grade',grades,j.grade)}</div><div class="form-row">${field('Зарплата от, ₽','min',j.min,'number','required min="1" max="10000000"')}${field('Зарплата до, ₽','max',j.max,'number','required min="1" max="10000000"')}</div><div class="form-row">${field('Город','city',j.city||state.company.city)}${select('Формат работы','format',['Удалённо','Гибрид','Офис'],j.format)}</div>${field('Технологии через запятую','stack',j.stack.join(', '),'text','required')}${textarea('Задачи, требования и условия','description',j.description||'','required minlength="30" maxlength="8000"')}</div>${formEnd(id?'Сохранить изменения':'Опубликовать')}</form>`,true);}
function apply(id){if(!state.roles.includes('candidate')){ensureRole('candidate','jobs');return;}const j=state.jobs.find(j=>j.id===id);if(!j)return;modal('Отклик на вакансию',esc(j.title)+' · '+esc(j.company),`<form id="apply-form" data-id="${id}"><div class="inline-note">${icon('user')}Компания получит ваше резюме и контакт: ${esc(state.user.email)}.${j.synthetic?' Это демовакансия, реальный работодатель сообщение не получит.':''}</div>${textarea('Сопроводительное письмо (необязательно)','letter','','maxlength="4000"')}${formEnd('Отправить отклик')}</form>`);}
function applicationReview(id){const a=state.applications.find(x=>x.id===id);modal('Ответить кандидату',esc(a.candidateName),`<form id="application-review" data-id="${id}">${select('Решение','status',['viewed','shortlisted','rejected'],a.status)}${textarea('Обратная связь','feedback',a.feedback||'','maxlength="2000"')}${formEnd('Отправить ответ')}</form>`);overlay.querySelectorAll('[name="status"] option').forEach(o=>o.textContent=statusLabel[o.value]);}
function taskForm(){modal('Задание от команды','Короткая практическая задача. Ответ проверяется человеком.',`<form id="task-form">${field('Название','title','','text','required')}${select('Направление','spec',specs,'Backend')}${textarea('Контекст, задача и критерии хорошего ответа','description','','required minlength="30" maxlength="5000"')}${formEnd('Опубликовать задание')}</form>`);}
function taskAnswer(id){const t=state.tasks.find(x=>x.id===id);modal(esc(t.title),esc(t.company),`<form id="task-answer" data-id="${id}"><p class="multiline detail-section">${esc(t.description)}</p>${textarea('Ваше решение или подход','answer','','required minlength="30" maxlength="8000"')}${formEnd('Отправить решение')}</form>`,true);}
function taskReview(id){const s=state.submissions.find(x=>x.id===id);modal('Обратная связь по заданию',esc(s.candidateName),`<form id="task-review" data-id="${id}"><p class="multiline">${esc(s.answer)}</p>${textarea('Что получилось и что улучшить','feedback','','required maxlength="3000"')}${formEnd('Отправить обратную связь')}</form>`,true);}
function chat(id){const context=state.invites.find(x=>x.id===id)||state.applications.find(x=>x.id===id);if(!context)return;const rows=state.messages.filter(m=>m.contextId===id).sort((a,b)=>a.created-b.created);modal('Диалог',esc(context.title||context.job?.title||'Обсуждение предложения'),`<div class="chat-thread">${rows.length?rows.map(m=>`<div class="chat-message ${m.owner===state.user.id?'mine':''}"><strong>${esc(m.author)}</strong><p>${esc(m.text)}</p><small>${date(m.created)}</small></div>`).join(''):'<p class="subtext">Начните разговор с вопроса о команде или следующем шаге.</p>'}</div><form id="message-form" data-id="${id}">${textarea('Сообщение','text','','required maxlength="4000"')}${formEnd('Отправить')}</form>`,true);}

let pdfExporting=false,pdfCache=null,pdfPreparationTimer;
function resumePDFKey(){return JSON.stringify([state.user?.id,state.user?.email,state.profile,state.privacy?.fspVisible,new Date().toDateString()]);}
function invalidateResumePDF(){pdfCache=null;clearTimeout(pdfPreparationTimer);}
function preparedResumePDF(){
 const key=resumePDFKey();
 if(pdfCache?.key===key)return pdfCache.promise;
 const entry={key,promise:null};
 entry.promise=requestData('/api/resume/pdf',{cache:'no-store'},'pdf',30000).then(file=>({...file,key})).catch(error=>{if(pdfCache===entry)pdfCache=null;throw error;});
 pdfCache=entry;return entry.promise;
}
function prepareResumePDF(){
 clearTimeout(pdfPreparationTimer);
 if(page!=='profile'||!state.authenticated||!state.roles.includes('candidate'))return;
 pdfPreparationTimer=setTimeout(()=>{if(page==='profile')preparedResumePDF().catch(()=>{});},600);
}
async function exportPDF(){
 if(pdfExporting)return;
 pdfExporting=true;clearTimeout(pdfPreparationTimer);
 const buttons=[...document.querySelectorAll('[data-action="pdf"]')],labels=buttons.map(b=>b.innerHTML);
 buttons.forEach(b=>{b.disabled=true;b.textContent='Готовим файл…';b.setAttribute('aria-busy','true');});
 try{
  const {blob,filename,key}=await preparedResumePDF();
  if(key!==resumePDFKey())throw new Error('Резюме изменилось. Скачайте обновлённый файл ещё раз.');
  const url=URL.createObjectURL(blob),link=document.createElement('a');
  link.href=url;link.download=filename;document.body.appendChild(link);link.click();link.remove();
  setTimeout(()=>URL.revokeObjectURL(url),60000);toast('PDF готов. Скачивание началось.');
 }catch(error){toast(error.message||'Не удалось скачать PDF.');}
 finally{pdfExporting=false;buttons.forEach((b,i)=>{b.disabled=false;b.innerHTML=labels[i];b.removeAttribute('aria-busy');});}
}
document.addEventListener('click',async event=>{const faq=event.target.closest('.faq-item > summary');if(faq){event.preventDefault();toggleFAQ(faq.parentElement);return;}if(event.target.matches('[data-backdrop]')){close();return;}const el=event.target.closest('[data-action]');if(!el)return;event.preventDefault();const {action,id}=el.dataset;switch(action){
case 'nav':go(el.dataset.page);break;
case 'survey-section':document.getElementById(el.dataset.target)?.scrollIntoView({behavior:'smooth',block:'start'});break;
case 'login':await loginApp();break;
case 'logout':await logoutApp();break;
case 'join':ensureRole(el.dataset.role||role,el.getAttribute('href')?.slice(1)||'dashboard');break;
case 'switch-workspace':modal('Выберите кабинет',esc(state.user?.email||''),`<div class="workspace-choices">${[['candidate','Кандидат','Резюме, навыки и предложения'],['employer','Работодатель','Подбор, приглашения и вакансии']].map(([r,h,p])=>`<button data-action="workspace" data-role="${r}"><span>${icon(r==='candidate'?'user':'briefcase')}</span><div><strong>${h}</strong><p>${p}</p></div>${state.roles.includes(r)?badge('Создан'):badge('Создать')}</button>`).join('')}</div><button class="text-button signout-link" data-action="logout">Выйти из аккаунта</button>`);break;
case 'workspace':close();ensureRole(el.dataset.role);break;
case 'close':close();break;
case 'legal':close();go('privacy');break;
case 'job-query':jobQuery=el.dataset.query;filter.spec='all';go('jobs');break;
case 'job-direction':filter.spec=el.dataset.spec;jobQuery='';go('jobs');break;
case 'reset-jobs':jobQuery='';filter.spec='all';render();break;
case 'reset-filters':filter={spec:'all',grade:'all',stack:'',format:'all',sort:'match',fsp:'all'};render();break;
case 'fsp-manage':fspManage();break;
case 'fsp-unlink':await mutate({action:'fsp-unlink'});break;
case 'filters':modal('Фильтры поиска','Уточняйте выдачу без потери запроса.',`<form id="filter-form"><div class="stack">${select('Специализация','spec',['all',...specs],filter.spec)}${select('Грейд','grade',['all',...grades],filter.grade)}${field('Технологии через запятую','stack',filter.stack)}${select('Формат','format',['all','Удалённо','Гибрид','Офис'],filter.format)}<div class="field"><label for="filter-fsp">Достижения ФСП</label><select id="filter-fsp" name="fsp"><option value="all" ${filter.fsp==='all'?'selected':''}>Любое</option><option value="with" ${filter.fsp==='with'?'selected':''}>Есть достижения</option><option value="without" ${filter.fsp==='without'?'selected':''}>Без достижений</option></select></div></div>${formEnd('Показать профили')}</form>`);overlay.querySelectorAll('option[value="all"]').forEach(o=>o.textContent='Любое');break;
case 'favorite':await mutate({action:'favorite',candidateId:id});break;
case 'candidate-detail':candidateDetail(id,el.dataset.applicationId);break;
case 'compare-candidate':if(compare.includes(id))compare=compare.filter(x=>x!==id);else if(compare.length<3)compare=[...compare,id];else{toast('Можно сравнить не более трёх кандидатов.');break;}render();break;
case 'open-comparison':comparison();break;
case 'clear-comparison':compare=[];render();break;
case 'invite':invite(id);break;
case 'edit-need':confirmNeed();break;
case 'save-need':{const form=document.getElementById('demand-form'),data=form?Object.fromEntries(new FormData(form)):{},text=data.query||query,changed=text!==query;if('team' in data){needContext=contextFields(data);contextDraft=null;}if(changed){query=text;needSpec='';needGrade='';needStack='';needConfirmed=false;activeNeed=null;await refresh();confirmNeed();toast('Подтвердите новую категорию перед сохранением.');break;}if(!state.need?.confirmed){confirmNeed();break;}query=text;activeNeed=null;const saved=await mutate({action:'need',...needContext,text,spec:needSpec||state.need.spec,grade:needGrade||state.need.grade,stack:state.need.stack,confirmed:true});if(saved&&changed){activeNeed=null;filter.spec=state.need?.spec||'all';filter.grade=state.need?.grade||'all';render();}break;}
case 'open-need':{const n=state.needs.find(n=>n.id===id);query=n.text;needSpec=n.spec;needGrade=n.grade;needStack=(n.stack||[]).join(', ');needConfirmed=true;needContext=contextFields(n.context);contextDraft=null;activeNeed=n;await refresh();filter={...filter,spec:state.need?.spec||n.spec,grade:state.need?.grade||n.grade};go('catalog');break;}
case 'delete-need':await mutate({action:'delete-need',id});break;
case 'category':{const same=filter.spec===el.dataset.spec&&filter.grade===el.dataset.grade;filter={...filter,spec:same?'all':el.dataset.spec,grade:same?'all':el.dataset.grade};render();break;}
case 'clear-context':needContext=contextFields(null);contextDraft=null;activeNeed=null;try{await refresh();render();}catch(e){toast(e.message);}break;
case 'offer-detail':await offerDetail(id);break;
case 'respond':await mutate({action:'invite-status',id,status:el.dataset.status});break;
case 'edit-profile':editProfile();break;
case 'edit-resume-details':editResumeDetails();break;
case 'resume-section':scrollResumeSection(el.dataset.section);break;
case 'resume-add':updateResumeEditor(el.dataset.kind);break;
case 'resume-remove':updateResumeEditor(el.dataset.kind,Number(el.dataset.index));break;
case 'pdf':exportPDF();break;
case 'new-job':if(state.roles.includes('employer'))jobForm();else ensureRole('employer','jobs');break;
case 'edit-job':jobForm(id);break;
case 'job-detail':jobDetail(id);break;
case 'job-status':await mutate({action:'job-status',id,status:el.dataset.status});break;
case 'apply':apply(id);break;
case 'review-application':applicationReview(id);break;
case 'previous-question':{const selected=app.querySelector('[name="answer"]:checked');if(selected)answers[testIndex]=Number(selected.value);if(testIndex>0){testIndex--;render();}break;}
case 'exit-test':modal('Завершить попытку?','Незавершённая попытка не изменит категорию.',`<div class="modal-actions">${button('Продолжить','close','',true)}${button('Выйти','confirm-exit-test')}</div>`);break;
case 'confirm-exit-test':test=null;result=null;go('tests');break;
case 'finish-test':test=null;result=null;go('dashboard');break;
case 'retry-test':test=null;result=null;render();break;
case 'new-task':taskForm();break;
case 'answer-task':taskAnswer(id);break;
case 'review-task':taskReview(id);break;
case 'chat':chat(id);break;
}});
// Keep digit positions stable while inserting thousands separators.
document.addEventListener('beforeinput',event=>{
 const input=event.target;if(!input.matches?.('[data-money]'))return;
 const pos=input.selectionStart;if(pos!==input.selectionEnd)return;
 if(event.inputType==='deleteContentBackward'&&input.value[pos-1]==='.')input.setSelectionRange(Math.max(0,pos-2),pos);
 if(event.inputType==='deleteContentForward'&&input.value[pos]==='.')input.setSelectionRange(pos,Math.min(input.value.length,pos+2));
});
document.addEventListener('input',event=>{
 const input=event.target;if(!input.matches?.('[data-money]'))return;
 const digits=input.value.slice(0,input.selectionStart).replace(/[^0-9]/g,'').length;
 input.value=formatMoneyInput(input.value);
 let caret=0,count=0;while(caret<input.value.length&&count<digits){if(/[0-9]/.test(input.value[caret]))count++;caret++;}
 input.setSelectionRange(caret,caret);
});
document.addEventListener('change',e=>{if(e.target.dataset.filter){filter[e.target.dataset.filter]=e.target.value;render();}});
document.addEventListener('submit',async event=>{const form=event.target;if(!form.id)return;event.preventDefault();const data=Object.fromEntries(new FormData(form));switch(form.id){
case 'onboard':{data.consent=form.elements.consent.checked;const candidate=form.dataset.role==='candidate';const r=await mutate({action:'onboard',role:form.dataset.role,...data},candidate?'survey':'dashboard');if(r&&candidate)toast('Профиль создан. Заполните анкету перед тестированием.');break;}
case 'home-search':jobQuery=data.query;filter.spec='all';go('jobs');break;
case 'job-search-form':jobQuery=data.query;filter.spec=data.spec;render();break;
case 'demand-form':if(!state.roles.includes('employer')){ensureRole('employer','catalog');break;}if(Number(data.budgetMin)&&Number(data.budgetMax)&&Number(data.budgetMax)<Number(data.budgetMin)){toast('Бюджет «до» должен быть не меньше бюджета «от».');break;}query=data.query;needSpec='';needGrade='';needStack='';needConfirmed=false;compare=[];if('team' in data)needContext=contextFields(data);contextDraft=null;activeNeed=null;try{await refresh();filter.spec=state.need?.spec||'all';filter.grade=state.need?.grade||'all';go('catalog');if(query.trim())confirmNeed();}catch(e){toast(e.message);}break;
case 'need-confirm-form':needSpec=data.spec;needGrade=data.grade;needStack=data.stack||'';needConfirmed=true;filter.spec=data.spec;filter.grade=data.grade;filter.stack='';try{await refresh();close();go('catalog');}catch(e){const error=form.querySelector('[data-error]');if(error)error.textContent=e.message;}break;
case 'filter-form':filter={...filter,...data};close();render();break;
case 'fsp-form':await mutate({action:'fsp-link',...data});break;
case 'profile-form':readResumeDraft();await mutate({action:'profile',...data,resume:resumeDraft});break;
case 'survey-form':{const formData=new FormData(form);await mutate({action:'survey',...data,roles:formData.getAll('roles'),softSkills:formData.getAll('softSkills')},'tests');break;}
case 'invite-form':await mutate({action:'invite',candidateId:form.dataset.id,...data});break;
case 'job-form':await mutate({action:'job',id:form.dataset.id,...data},'jobs');break;
case 'apply-form':await mutate({action:'apply',jobId:form.dataset.id,...data});break;
case 'application-review':await mutate({action:'application-status',id:form.dataset.id,...data});break;
case 'settings-form':await mutate({action:'settings',...Object.fromEntries(['visible','consent','notifications','fspVisible'].map(k=>[k,form.elements[k].checked]))});break;
case 'company-form':await mutate({action:'company',...data});break;
case 'start-test-form':if(busy)return;busy=true;try{const r=await api({action:'test-start',...data});test=r.test;testIndex=0;answers=[];result=null;render();}catch(e){toast(e.message);}finally{busy=false;}break;
case 'answer-form':if(busy)return;if(Date.now()>=test.expires){testClock();return;}answers[testIndex]=Number(data.answer);if(testIndex<test.questions.length-1){testIndex++;render();window.scrollTo({top:0});}else{busy=true;try{const r=await api({action:'test-submit',id:test.id,answers});result=r.result;await refresh();render();toast(r.message);}catch(e){toast(e.message);}finally{busy=false;}}break;
case 'task-form':await mutate({action:'task',...data});break;
case 'task-answer':await mutate({action:'task-answer',id:form.dataset.id,...data});break;
case 'task-review':await mutate({action:'task-review',id:form.dataset.id,...data});break;
case 'message-form':{const context=form.dataset.id;const r=await mutate({action:'message',contextId:context,...data});if(r)chat(context);break;}
}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1)||'home';if(next!==page){page=next;close();render();window.scrollTo({top:0});}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')close();if(e.key==='Tab'&&overlay.firstElementChild){const els=[...overlay.querySelectorAll('button:not([disabled]),a[href],input:not([disabled]),select,textarea')];if(e.shiftKey&&document.activeElement===els[0]){els.at(-1)?.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===els.at(-1)){els[0]?.focus();e.preventDefault();}}});
async function boot(){const initialPage=page;try{await refresh();render();if(initialPage.startsWith('onboarding-'))onboarding(initialPage.endsWith('employer')?'employer':'candidate');}catch(e){app.innerHTML=header()+`<main class="boot-error"><h1>Не удалось загрузить сервис</h1><p>${esc(e.message)}</p><button class="button" onclick="location.reload()">Повторить</button></main>`;}}
boot();

setInterval(async()=>{if(!state.authenticated||busy||test||overlay.firstElementChild||document.hidden||!['dashboard','offers','invites','applications','tasks'].includes(page))return;const previous=JSON.stringify([state.invites,state.applications,state.tasks,state.submissions,state.messages]);try{await refresh();if(previous!==JSON.stringify([state.invites,state.applications,state.tasks,state.submissions,state.messages]))render();}catch{}},20000);
